GimCorpus.put(362,0,[[1,1,"מצות עשה להיות כל הקרבנות תמימים וכו'. בסיפרא:",1,0],[1,2,"ומ\"ש וכל המקדיש בהמה שיש בה מום לגבי המזבח עובר בלא תעשה ולוקה על הקדשו שנאמר כל אשר בו מום לא תקריבו מפי השמועה למדו שזו אזהרה למקדיש בעלי מומין. בפרק קמא דתמורה (דף ו').",1,0],[1,2,"ומה שכתב אפילו הקדישו לדמים לוקה וכו'. שם (דף ז') אמר רבא השתא דאמור טעמא דבעל מום דלקי משום דבזיא מילתייהו אפילו מקדיש ליה לדמי נסכים נמי לקי ותניא כוותיה דרבא וכתבו התוספות דה\"ה למקדיש לדמי עולה ואיני יודע למה למדוהו בה\"ה דהא כל שכן הוא שהרי פירש\"י אפילו אקדשיה לדמי נסכים דהשתא ליכא בזיון כל כך שאין במינו ראוי לנסכים עכ\"ל. ונראה שהנוסחא האמיתית בדברי רבינו אפילו הקדישו לדמי נסכים:",2,0],[1,3,"המתכוין לומר שלמים ואמר עולה וכו' לא אמר כלום. בפרק שלישי דתרומות (משנה ח').",1,0],[1,3,"ומה שכתב לפיכך המתכוין לומר על בעל מום עולה והקדישו שלמים וכו' אינו לוקה. פשוט הוא:",2,0],[1,3,"מי שדימה שמותר להקדיש בעל מום למזבח. בפרק שני דתמורה (דף י\"ז) תנן עשה שוגג כמזיד בתמורה ולא עשה שוגג כמזיד במוקדשין ובגמרא מאי טעמא וכו' אמר קרא יהיה קדש לרבות שוגג כמזיד היכי דמי שוגג כמזיד אמר חזקיה כסבור שהוא מותר להמיר דכוותה גבי קדשים כסבור מותר להקדיש בעלי מומין למזבח גבי תמורה לקי גבי קדשים לא לקי. וכתב הראב\"ד על דברי רבינו טעה בזה כי מי שדי בדברי רש\"י שכתב גבי תמורה לקי דרבי ביה קרא שוגג כמזיד גבי מה שמותר להקדיש בעל מום למזבח וכו'. ותירוץ השגה זו מבואר קדשים לא לקי דלא מצינו מלקות אלא במזיד ובהתראה עכ\"ל. ועל מה שכתב הראב\"ד דהוי הקדש טעות יש לדון דלא מיקרי הקדש טעות אלא כגון אומר שור שחור שיצא מביתי ראשון ויצא לבן שנתכוון להקדיש גוף אחד ונמצא גוף אחר אבל אם דימה שמותר להמיר שוגג מיקרי ולא טעות:",3,0],[1,4,"השוחט בעל מום לשם קרבן לוקה וכו'. וכן המקטיר אימורי בעלי מומין על המזבח לוקה וכו'. בפרק קמא דתמורה (דף ו') ודקדק רבינו לכתוב לשם קרבן משום דאמרינן בגמרא שומע אני אף קדשי בדק הבית תלמוד לומר ואל פתח אהל מועד לא הביאו וכו' שאין ראוי לפתח אהל מועד אין חייבין עליו משום שחוטי חוץ כלומר והוא הדין לשוחט בעל מום שאינו חייב משום בעל מום.",1,0],[1,4,"ומה שכתב נמצאת למד שאם הקדיש בעל מום ושחטו וכו' לוקה ד' מלקיות. שם אלא ששם אמרו שעובר משום ה' שמות משום דמני בל תקטירו ב' לאוין בל תקטירו כולו בל תקטירו מקצתו וכתב רבינו בסה\"מ שלו (מצוה צ\"ד) דאמרינן בפרק קמא דתמורה (דף ז':) המעלה איברי בעלי מומין על גבי המזבח אמר אביי עובר משום בל תקטירו כולו ובל תקטירו מקצתו רבא אמר אין לוקין על לאו שבכללות מיתיבי המקדיש בעלי מומין לגבי מזבח עובר משום ה' שמות אלמא לוקין על לאו שבכללות וכו' תיובתא דרבא תיובתא הנה נתבאר לך שזה שאמרו עובר בה' אמנם הוא עם סברתו שסובר שלוקין על לאו שבכללות ולכן ימנה הלאו שכולל כולם ומקצתם בשני שמות וזה הוא המפורסם מדעת אביי בכל מקום ולדעת רבא שאמר אין לוקין על לאו שבכללות אמנם יתחייב מלקות אחת וכו' ויהיו כולם ארבעה לאוין לבד עכ\"ל. ומשום דקי\"ל בעלמא דהלכה כרבא לגבי אביי הילכך לא חיישינן לההיא ברייתא דסברה דלוקין על לאו שבכללות ויש לתמוה דכיון דאיתותב רבא מברייתא היכי אפשר דנקטינן כוותיה כיון דלא אשכחן תנא דפליג אהאי ברייתא וי\"ל דכיון דלא מני גמרא הא עם יע\"ל קג\"ם דהלכה כאביי משמע דקים ליה לגמרא דהלכה כרבא בהא ולא קי\"ל כההיא ברייתא ואיכא תנא דפליג עלה ואע\"ג דלא אידכר ההוא תנא הכא בגמרא. ודע דבנוסחא דידן בגמרא הגירסא מהופכת וגירסת רבינו עיקר:",2,0],[1,5,"אחד בעל מום קבוע או בעל מום עובר וכו'. ז\"ל רבינו בספר המצות שלו צ\"ה הזהירנו מהקריב בעל מום עובר והוא אמרו לא תזבח לה' אלהיך שור ושה אשר יהיה בו מום ונתבאר בספרי שבבעל מום עובר הכתוב מדבר וזה גם כן ילקה עליו כשעבר והקריבו עכ\"ל. וטעמו ממה שפירשו שם על פסוק זה מנין לבעל גרב ובעל יבלת ובעל חזזית תלמוד לומר כל דבר רע והרי בעל יבלת מום עובר הוא וכן בעל גרב לח ובעל חזזית ומייתי להו מהאי קרא ואע\"ג דבקרא דדריש מיניה בעל מום לא כתיב אלא לא תזבח איכא למימר דכיון דחזינן דקפיד קרא בבעל מום עובר לענין זביחה כמו בבעל מום קבוע ילפינן מיניה דה\"ה לשאר לאוין והרמב\"ן בהשגותיו על סה\"מ כתב וז\"ל אני אומר שהמניעה במום קבוע ועובר לאו אחד תמנה שהכתוב מרבה והולך עד שאסר כל מום בין קבוע בין עובר וגם בלאו הראשון נתרבו וכך אמרו בסיפרא וישנו בגמרא תמורה אשר בו מום אין לי אלא מום קבוע מום עובר מנין תלמוד לומר כל אשר בו מום ובשניהם עובר בכל חמשה שמות הללו ונאמרו הכתובים להשלים האיסור ולא אמרו בסיפרי בפסוק לא תזבח לה' אלהיך שור או שה אשר יהיה בו מום שבא למום עובר בלבד אלא גם שם נתרבה הכל וזה מאמרם שם אין לי אלא תם ונעשה בעל מום ממעי אמו מנין ת\"ל כל דבר רע מנין בעל גרב ובעל יבלת ובעל חזזית ת\"ל מום כל דבר רע מנין לזקן וחולה וכו' עכ\"ל:",1,0],[1,6,"ולא קרבנות ישראל בלבד וכו'. מבואר בכתוב:",1,0],[1,7,"המטיל מום בקדשים וכו' מפי השמועה למדו שזה אזהרה שלא יתן בו מום. בסיפרי ובפרק פסולי המוקדשין (דף ל\"ד):",1,0],[1,7,"ואינו לוקה אלא בזמן שבית המקדש קיים וכו'. בפרק קמא דעבודה זרה (דף י\"ג) אהא דתניא אין מקדישין וכו' בזמן הזה ואם הקדיש בזמן הזה בהמה נועל בפניה והיא מתה מאליה וכו'. ולשוייה גיסטרא אמר רבא מפני שנראה כמטיל מום בקדשים נראה מום מעליא הוא ה\"מ בזמן שב\"ה קיים דחזי להקרבה השתא דלא חזי להקרבה לית לן בה ופירש\"י ה\"מ דהוי מטיל מום גמור ואסור משום כל מום לא יהיה בו בזמן ב\"ה דקרינא ביה תמים יהיה לרצון להקריב אבל השתא נראה בעל מום הוא ולא אסור מדאורייתא אבל דעת רבינו דאסור מדאורייתא אלא שאינו לוקה:",2,0],[1,8,"הטיל מום בקדשים וכו'. פלוגתא דתנאי בברייתא בפ' פסולי המוקדשין (דף ל\"ג:) ופסק כחכמים:",1,0],[1,9,"אחד המטיל מום בקדשים עצמם וכו' וכן המטיל מום בתשיעי של טעות עשירי אינו לוקה. בפרק שלישי דתמורה (דף כ\"א):",1,0],[1,10,"המקדיש בעל מום למזבח וכו'. בפרק קמא דתמורה (דף ה') המקדיש בעלי מומין לגבי מזבח אע\"פ שהוא בלא תעשה מה שעשה עשוי.",1,0],[1,10,"ומה שכתב ותפדה בערך הכהן ותצא לחולין ויביא בדמיה קרבן. בסוף תמורה תניא (דף ל\"ב) אם כל בהמה טמאה אשר לא יקריבו ממנה קרבן לה' והעמיד את הבהמה לפני הכהן והעריך הכהן אותה בבעלי מומין שיפדו הכתוב מדבר וכתב שם רש\"י דע\"כ בקדשי מזבח מיירי.",2,0],[1,10,"ומה שכתב וכן הדין בבהמת קדשים שנפל בה מום. שם אמרינן לר' יוחנן דהאי ברייתא כוותיה דאותה למעוטי בעל מום מעיקרו שאינו בכלל העמדה והערכה לדברי הכל וקשה היכי רבינו לא מפליג בינייהו ואפשר שרבינו פסק כלוי דאמר התם הכל היו בכלל העמדה והערכה ואפילו בעל מום ואע\"ג דאקשינן ללוי והכתיב אותה ואסיקנא בקשיא אשכחן דמסיק בקשיא והלכתא כוותיה וכיון דלוי קשיש מרבי יוחנן פסק רבינו כוותיה ועי\"ל דכרבי יוחנן פסק רבינו דע\"כ לא אמר ר' יוחנן אותה למעוטי בעל מום מעיקרו אלא לומר דבעל מום מעיקרו אפילו אם מת נפדה דלא בעינן בהו והעמיד אבל בכשהוא חי לדברי הכל נפדה הוא בערך הכהן וזה עיקר שהרי כן כתב רבינו בסמוך גבי מה בין בעלת מום קבוע לבעלת מום עובר:",3,0],[1,10,"ומצות עשה היא לפדות קדשים שנולד בהם מום וכו'. בפ\"ב דבכורות (דף ט\"ו ע\"א):",4,0],[1,10,"וכבר ביארנו בערכין פ״ה שזה שנאמר וכו'. בסוף תמורה דף ל״ג ע״א ובריש פרק על אלו מומין (בכורות ל״ז ע״ב):",5,0],[1,11,"מה בין בעלת מום קבוע לבעלת מום עובר כו'. בפ\"ב דבכורות (דף ט\"ו:).",1,0],[1,11,"ומ\"ש ואם נתעברה קודם שתפדה וילדה אחר פדיון הולד חולין. ג\"ז שם.",2,0],[1,11,"ומ״ש ואם מתה קודם שתפדה נפדית אחר שתמות וכו'. במשנה שם (דף י״ד) ובפ' הזרוע (חולין דף ק״ל).",3,0],[1,11,"ומ\"ש אבל המקדיש בעלת מום עובר או תמימה ואחר שהקדישה נולד לה מום קבוע אם מתה קודם שתפדה תקבר וכו'. במשנה פ\"ב דבכורות ופ' הזרוע.",4,0],[1,11,"ומ\"ש ואם נשחטה קודם שתפדה ה\"ז נפדית. בפ\"ק דמעילה קדשי מזבח תמימים ונעשו בעלי מומין ועבר ושחטן רבי אומר יקברו וחכ\"א יפדו.",5,0],[1,11,"ומה שכתב נפדית כל זמן שהיא מפרכסת. בפ\"ב דחולין (דף ל') וכ\"ת דבעי העמדה והערכה והתנן שחט בה שנים או רוב שנים ועדיין היא מפרכסת הרי היא כחיה לכל דבריה.",6,0],[1,11,"ומ\"ש ואם ילדה יקרב ולדה. בפ\"ב דבכורות (דף ט\"ז) אמרינן על קדם הקדשן את מומן ולדותיהן שנולדו לפני פדיון מקדש קדשי ואמרינן דבפרק אלו קדשים איפליגו אי קדשי ליקרב או אי קדשי לרעייה ופסק רבינו כשמואל ורבא ולא כבר פדא ורב פפא משום דשמואל ורבא הוו מארי דגמרא טפי מינייהו:",7,0],[1,11,"נתעברה קודם שתפדה וילדה אחר וכו'. בפ\"ב דבכורות (דף י\"ד) שנינו גבי קדם הקדשן את מומן ולדן אסור לאחר פדיון ומפרש בגמרא דמיירי באיעבר לפני פדיון ואתיליד לאחר פדיון ואמרינן בגמרא (דף ט\"ו:) אותן ולדות מה תהא עליהן אמר רב הונא כונסן לכיפה והן מתין דהיכי ליעבד לקרבינהו מכח קדושה דחויה קא אתו לפרקינהו לא אלימי למתפס פדיונן אמרי במערבא משום רבי חנינא סמוך לפדיונן מתפיסן לשם אותו זבח ופרש\"י קדושה דחויה דאית בהו תרתי לריעותא חדא דאמותן בעלי מומין שנראו ונדחו ועוד דלאחר פדיון נולדו והן עצמן אין יכול להתפיסן לקדושה גמורה להקריב והואיל ואידחו תו לא מיחזו. לא אלימי למיתפס פדיונן בקדושתן כדי שיצאו הם לחולין שכבר יצאה קדושתן אגב פדיון דאמן וכו'. סמוך לפדיון אמן מתפיסן לשם אותו זבח דהשתא חיילא עלייהו קדושה לעצמן דחשבינהו ולא פקעא קדושתייהו על ידי פדיית אמן עכ\"ל ואמרינן בגמרא בעא מיניה רבינא מרב ששת מהו שמתפיסם לכל זבח שירצה א\"ל אין מתפיסן (אלא לשם אותו הזבח) ותניא כוותיה ופסק רבינו כרבי חנינא משום דרב ששת ורבינא דבתראי נינהו סברי כוותיה וברייתא דתניא כוותיה דרב ששת כוותיה אתיא. ויש בקצת ספרי רבינו טעות סופר והנוסחא הנכונה לפי שאינו יכול להקריבו מכח אמו לפי שבא מכח קדושה דחויה:",8,0],[1,12,"כל פסולי המוקדשין כשיפדו וכו'. משנה בפרק פסולי המוקדשין (דף ל\"א:):",1,0],[1,12,"התפיס בכור לבדק הבית וכו'. בפרק התערובות (דף ע\"ה:) בעיא דאיפשיטא:",2,0],[2,1,"כל המומין הפוסלין באדם ובבהמה חמשים וכבר נמנו. בפ\"ז מהלכות ביאת המקדש:",1,0],[2,2,"ומ״ש ויש מומין אחרים מיוחדים בבהמה וכו'. קשה לי דהא חטיה החיצונות והפנימיות למה לא יפסלו באדם דהא [אחר שנשנו מומין האמורין בבכור שנינו בריש פרק מומין אלו] (בכורות דף מ״ג) מומין אלו פוסלין באדם.",1,0],[2,2,"ומ\"ש רבינו וכ\"ג הם ואלו הם אם היה גלגל עינה עגול כשל אדם. בפרק אלו מומין במשנה (דף מ') את שגלגל עינו עגול כשל אדם ובגמרא למימרא דלאו היינו אורחיה ורמינהו המפלת כמין בהמה חיה ועוף וכו' מאי טעמא דרבי מאיר הואיל וגלגל עינו עגול כשל אדם אמר רב יוסף ל\"ק הא באוכמא הא בחיורא ופירש רש\"י באוכמא שחור של עין הבהמה אינו עגול כשל אדם הא בציריא כל בית מושב הלובן והוא עגול כשל אדם ע\"כ נראה שהוא גורס הא באוכמא הא בציריא. ויש לתמוה על רבינו שסתם דבריו ולא חילק בזה אולי לא היה זה בגירסתו.",2,0],[2,2,"ומ\"ש עינה אחת גדולה כשל עגל והשניה קטנה כשל אווז אבל אם היתה אוזן גדולה ואוזן קטנה אפילו קטנה עד כפול כשר. שם (דף מ':) רבי חנינא בן אנטיגנוס אומר את שיבלת בעינו וכו' עינו אחת גדולה ואחת קטנה אזנו אחת גדולה ואחת קטנה במראה אבל לא במדה ובגמרא תנא גדולה כשל עגל קטנה כשל אווז אזנו אחת גדולה וכו' ורבנן עד כמה תניא אחרים אומרים אפילו אינה לשנייה אלא כפול כשירה. ומשמע דעינו גדולה כשל עגל וכו' רבנן קאמרי לה והכי משמע בריש בכורות (דף ג') ולפיכך פסק רבינו כן ואמרינן בריש בכורות דדוקא עינה אחת גדולה והשניה קטנה הוי מום בבהמה אבל אם היו שתי עיניה גדולות או שתיהן קטנות בבהמה כשר ובאדם פסול וזהו שדקדק רבינו לכתוב כאן במומי בהמה עינה אחת גדולה והשניה קטנה ובפ\"ח מהלכות ביאת מקדש גבי מומי אדם כתב מי שעיניו גדולות או שעיניו קטנות כלומר אפילו שתיהן גדולות או שתיהן קטנות דכשר בבהמה פסול באדם וכל שכן אם עינו אחת גדולה והשניה קטנה דאף בבהמה פסול:",3,0],[2,2,"אם יש בלובן עינה יבלת שיש בה שיער. בפרק על אלו מומין (בכורות דף מ':) על אלו מומין שוחטין את הבכור את שיבלת בעינו ורמינן עלה הא דתנן אלו שאין שוחטים עליהם לא במקדש ולא במדינה וכו' בעל יבלת ושני אידי ואידי בעיניו ולא קשיא הא בשחור הא בלבן והא אין מומין בלבן אלא אידי ואידי בלבן ואמר ר״ל ל״ק הא דאית בה שער הא דלית בה שער ומשמע שרבינו אינו מפרש כפירש״י אבל הוא מפרש אידי ואידי מתניתין דעל מומין אלו שוחטין את הבכור את שיבלת בעיניו ומתניתין דאין שוחטין עליהם לא במקדש ולא במדינה בלבן ול״ק הא דהוי מום בדאית בה שער וההיא דאין שוחטין עליהם לא במקדש ולא במדינה בדלית בה שער ומ״מ ק״ל דמשמע דבשחור פשיטא דהוי מומא וכן פירש ה״ר עובדיה וא״כ יש לתמוה על רבינו דמשמע מדבריו דדוקא בלובן הוי מום ולא בשחור דאם לא כן הל״ל אם יש אפילו בלובן עיניה יבלת וצריך לדחוק ולומר דאם יש בלובן עיניה דנקט רבינו לרבותא נקטיה וכל שכן בשחור. ועוד יש לתמוה דכיון שהקשה והא אין מומין בלבן היכי מתרץ אידי ואידי בלבן ול״ק הא דאית בה שיער הא דלית בה שיער ואי אית בה שיער מאי הוי והא אין מומין בלבן ויש לדחוק ולומר דהכי מתרץ ליה כי שמיע לך דאין מומין בלבן ה״מ ביבלת שאין בה שער אבל ביש בה שער בלבן נמי הוי מום:",4,0],[2,2,"אם ניקב העור שבין שני חוטמיה במקום הנראה. בתוספתא דבכורות פ״ד ניקבו חוטמיו זה לתוך זה בפנים לא ישחוט מבחוץ ישחוט פירוש מבפנים לא ישחוט במדינה מפני שאינו מום מבחוץ ישחוט שהוא מום ובגמרא פרק על אלו מומין (בכורות דף ל״ט) תנו רבנן ניקבו חוטמיו זה לתוך זה מבחוץ הרי זה מום מבפנים אינו מום:",5,0],[2,2,"פיה דומה לשל חזיר פרוס וכו'. בפרק על אלו מומין (בכורות דף מ'):",6,0],[2,3,"חטיה החיצונות וכו'. משנה שם (דף ל\"ט) חטיו החיצונות שנפגמו שנגממו והפנימיות שנעקרו ובספרי רבינו כתוב שניקבו ונראה שטעות סופר הוא אלא שבסמ\"ג מצאתי כמו שכתוב בספרי רבינו ונראה שנוסחא אחרת היתה להם וכתב סמ\"ג חטיה החיצונות יינציב\"א בלע\"ז ופנימיות הם שהשינים הגדולות קבועים בהם:",1,0],[2,4,"אם ניטלו קרניה וזכרותן עמהם ולא נשאר מהם כלום. בפרק מומין אלו (בכורות דף מ״ד) אמר אמימר ניטלו קרניהן וזכרותן עמהם פסולה ואין פודין עליהם ניטלו טלפים וזכרותן עמהם פסולה ונפדין עליהם מיתיבי ניטלו קרנים וטלפים וזכרותן עמהם פסולים ונפדין עליהם לא קשיא הא דאתעקר אתעקורי הא דאיגום איגומי [דאיגום איגומי] פסול ורמינהו פרה שקרניה וטלפיה שחורים יגוד תרגמא זעירי מעילוי זכרות. ופירש״י זכרותן היינו עצם התחוב בתוך הקרנים זכרות הטלפים והיינו עצם שבתוך הטלפים דזו היא כף הרגל. ואין נפדין עליהם וכו'. דלא הוי מום גמור אלא לאיפסולי. ומדאמרינן הא דאתעקר איתעקורי הא דאיגום איגומי וכן מדתרגמא זעירי מעילוי זכרות משמע בהדיא דכל שניטל מהזכרות אפילו איגום איגומי פסולה ולא שאני לן בין אתעקר אתעקורי לאיגום איגומי אלא לענין אם נפדין עליהם וכ״כ רבינו לקמן בפרק זה גבי חליים שהן פוסלין ואין נפדין עליהם אם נגממו קרניו אע״פ שנשאר מזכרותן מעט סמוך לבשר תפדה והטעם פשוט משום דכיון דמימרא דאמימר בקרנים אוקימנא באיגום איגומי סיפא דלישניה בטלפים ע״כ מיתוקמא נמי באיגום איגומי ואפ״ה אמר דנפדים עליהם אלמא דבטלפים אפילו איגום איגומי הוי מום קבוע לפדות עליו.",1,0],[2,4,"ומה שכתב אבל נקבה שיש לה קרנים כשירה. ברייתא שם יש דברים שהם כמומין ואינם כמומין וכו' ואלו הם עז שאין לו קרנים ורחל שיש לה קרנים ומשמע לי דהיינו בעז שאין לו קרנים מתחלת ברייתו דומיא דרחל שיש לה קרנים ועוד דאילו בהיו לו וניטלו הא אמרינן בסמוך דפסול ולפי זה יש לתמוה על רבינו למה לא כתב דין זה ואפשר שרבינו מפרש דעז שאין לו קרנים דמכשר בברייתא היינו בניטלו קרניו בלא זכרות:",2,0],[2,4,"אם נפגם העור שחופה את גיד הבהמה. במשנה (דף ל\"ט:) בפרק על אלו מומין נפגם הזובן ובגמרא אמר רבי אלעזר נפגם ולא ניטל כיס ולא זכרות ופירש\"י הזובן זהו נרתק שהגיד חבוי בו. נפגם הזובן הוי מום דלא הדרא בריא ולא ניטל דניטל לא הוי מום דחוזר לאיתנו כיס אם נפגם הוי מום אבל זכרות גיד עצמו שנפגם לא הוי מום דמעלה ארוכה עכ\"ל ולא ידעתי למה קיצר רבינו מלהזכיר זה.",3,0],[2,4,"ומ\"ש אם נפגמה הערוה של נקבה. שם במשנה:",4,0],[2,4,"אם נפגם הזנב מן העצם אבל לא מן הפרק. שם במשנה ופירש\"י מן הפרק אם נפגם בין הפרקים מעלה ארוכה.",5,0],[2,4,"ומ\"ש אם היה ראש הזנב מפוצל לשנים כשני עצמים. שם במשנה היה ראש הזנב מפציל עצם כשני עצמים ומפרש בתוספתא שהיה ראש הזנב מופצל לשני עצמות.",6,0],[2,4,"ומה שכתב אם היה בין חוליא לחוליא מלא אצבע כשר. גם זה שם במשנה:",7,0],[2,4,"אם היה הזנב קצר וכו' ובטלה אורך שתי חוליות מום וכו'. שם משנה וגמרא:",8,0],[2,4,"זנב הגדי שהיה רך ומדולדל דומה לשל חזיר. שם (דף מ':) במשנה זנב הגדי שהוא דומה לשל חזיר ובגמרא אמר רב פפא לא תימא דקטינא אלא דכריכא אע\"ג דאלימא ופרש\"י כריכא עגולה שזנב הטלה הוי רחבה יתר על עביה. קטינא דקה מאד עכ\"ל. וכתב הראב\"ד על דברי רבינו דומה שהוא גורס דרכיכא וקטינא וכו':",9,0],[2,4,"אם נשבר עצם מן הזנב. נלמד מתוספתא דבסמוך דלא הכשיר בנשתברו רוב צלעותיו אלא מפני שאינם בגלוי אבל נשבר עצם מן הזנב מאחר שהוא בגלוי הוי מום:",10,0],[2,4,"אבל אם נשבר עצם מצלעותיו כשר וכו'. בתוספתא דבכורות פ\"ד נשתברו רוב צלעותיו או שהיה בו מום מבפנים אינו מום שנאמר עור או פסח מה עור ופסח מומין [המיוחדין מום] שבגלוי. ובגמרא (דף ל\"ט) פרק על אלו מומין בעי אם יש מחוסר אבר מבפנים למאי אי לבכור פסח או עור כתיב או לקדשים עורת או שבור כתיב ופרש\"י פסח או עור כתיב דמשמע בגלוי אין בסתר לא:",11,0],[2,5,"בעלת חמש רגלים וכו'. משנה פרק על אלו מומין (בכורות דף מ'):",1,0],[2,5,"אם היתה אחת מרגליו וידיו וכו'. שם במשנה שרגליו קלוטות כשל חמור ובגמרא אמר רב פפא לא תימא דעגולין ולא סדיקן אלא כיון דעגילן אע\"ג דסדיקן:",2,0],[2,5,"אם נגממו טלפיה וכו'. כבר נתבאר בפרק זה אצל ניטלו קרניה:",3,0],[2,6,"כל מום מע״ג מום המנויים בבהמה וכו'. בס״פ על אלו מומין (בכורות דף מ״א:) תנן על אלו מומין שוחטין את הבכור ופסולי המוקדשין נפדין עליהם.",1,0],[2,6,"ומ\"ש חוץ מזקן וחולה ומזוהם שאע\"פ שאינו כשר לקרבן אינו נפדה וכו'. שם במשנה ואלו שאין שוחטין עליהן לא במקדש ולא במדינה חוורור והמים שאינן קבועים וחוטיו הפנימיות שנפגמו אבל לא שנעקרו ובעל גרב ובעל יבלת ובעל חזזית וזקן וחולה ומזוהם ושנעבדה בו עבירה ושהמית אדם ע\"פ עד אחד או ע\"פ הבעלים וכתב רבינו בפירוש המשנה לא ישחוט עליהם במדינה לפי שאינן מומין קבועים:",2,0],[2,7,"ומ\"ש ארבעה מומין עוברים יש באדם ובבהמה. במשנה (דף מ\"ג) מומין אלו בין קבועים בין עוברים פוסלין באדם.",1,0],[2,7,"ומ\"ש ואלו הן גרב לח. נתבאר במה שכתבתי בפ\"ז מביאת המקדש דהיינו בלח מבפנים ומבחוץ שהוא יכול להתרפא.",2,0],[2,7,"ומ\"ש חזזית שאינה מצרית. נתבאר שם.",3,0],[2,7,"ומ\"ש מים שיורדים בעין ואינן קבועים סנוירים שאינם קבועים. היינו דתנן בפ' הנזכר (דף מ\"א) חוורור והמים שאינם קבועים גבי שאין שוחטין עליהם לא במקדש ולא במדינה:",4,0],[2,9,"יש ארבעה חוליים אחרים וכו' ואלו הם מי שבלובן עינו יבלת שאין בה שיער. כבר כתבתי בפרק זה דבגמרא אוקימנא הא דתנן גבי אלו שאין שוחטין עליהן לא במקדש ולא במדינה בעל יבלת כשהיה בלבן יבלת שאין בה שער.",1,0],[2,9,"ומה שכתב אם נגממו קרניו אף על פי שנשארו מזכרותן מעט סמוך לבשר. נתבאר בפרק זה.",2,0],[2,9,"ומה שכתב אם נפגמו חיטיו הפנימיות. במשנה שכתבתי בסמוך:",3,0],[2,9,"ומה שכתב וכן בהמת קדשים שנעבדה בה עבירה או שהמיתה את האדם וכו'. מפרש במשנה הנזכרת ובפרק כל האסורים תניא הרובע והנרבע הם כקדשים שקדם מום עובר להקדשן וצריכים מום קבוע לפדות עליהם:",4,0],[2,10,"בהמה שנולד בה אחד מהטרפיות וכו'. בר\"פ המזבח מקדש אמרינן דטריפה פסולה מעל גבי המזבח ובר\"פ התערובות (דף ע\"א:) אמרינן דטריפה שנתערבה בזבחים ירעו עד שיסתאבו.",1,0],[2,10,"ומה שכתב רבינו הרי הוא אומר הקריבהו נא לפחתך. יש לתמוה שהרי בתורת כהנים ובפרק ו' דתמורה (דף כ\"ט) דורש כשהוא אומר מן הבקר למטה וכו' להוציא את הטריפה משמע שמן התורה הוא דהא דריש לה מקרא ובפרק בתרא דבכורות (דף נ\"ז) יליף דטרפה פסול לקרבן בגזירה שוה ואפשר שסובר רבינו דסמך בעלמא הוא דמסמיך להו אקרא ואגזירה שוה דהא קיימא לן דלא מיפסיל משום מום אלא בגלוי דוקא אי נמי דה\"ק אפילו לא היה בה איסור מן התורה הוי ליה לפסלה משום הקריבהו נא לפחתך.",2,0],[2,10,"ומ\"ש ואע\"פ שאינה ראויה לקרבן אין פודין אותה וכו'. משנה בתמורה (דף ל') ס\"פ כל האסורים על גבי המזבח:",3,0],[2,11,"ומ״ש נשחטה ונמצאת טרפה הרי זה תצא לבית השרפה. בפרק כיצד צולין (פסחים דף פ״ב) אמרינן דמדכתיב בקדש באש תשרף לימד על כל פסולים שבקדש בשריפה:",1,0],[2,11,"וכן אם נמצא אחד מאיבריה הפנימיים חסר וכו' הרי זו אסורה למזבח ותשרף וכו'. בפרק על אלו מומין (בכורות דף ל״ט) בעי רב אחדבוי בר אמי יש מחוסר אבר מבפנים או אין מחוסר אבר מבפנים וכו' לאישחוטי ולאיפרוקי לא איבעי' לן כי מיבעי' לן לאיפסולי מאי תמים יהיה לרצון אמר רחמנא תמים אין חסרון לא או דילמא תמים יהיה לרצון כל מום לא יהיה בו מה מום מאבראי אף חסרון מאבראי ת״ש ואת שתי הכליות ולא בעל כוליא אחת ולא בעל ג' כוליות ותניא אידך יסירנה לרבות בעל כוליא אחת וכו' לימא בהא קא מיפלגי דמר סבר חסרון מבפנים שמיה חסרון וכו' ולא קשיא וכו' ופירש רש״י לאישחוטי בכור על חסרון שבפנים ולאפרוקי קדשים לא מיבעי' דלא חשיב מומא כולי האי:",2,0],[2,12,"אי זו היא סנורים קבועים וכו'. משנה וגמרא בפרק על אלו מומין (בכורות דף ל״ח):",1,0],[2,13,"ובמה יודע שהמים קבועים וכו' עד הרי אלו קבועים ודאי. משנה וגמרא שם:",1,0],[2,14,"ומ\"ש ואם חסר א' מכל אלו הרי זה ספק וכו' עד סוף הפרק. הכל שם בעיא דלא איפשיטו זולת שבנוסחא דידן בגמרא (דף ל\"ט) קודם שתייה ודאי מעלי לה (בשערי) לאחר שתייה מאי ורבינו גריס איפכא. ודע שאמרו שם את\"ל בסעודה ראשונה. וא\"ת דלפי שיטת רבינו שהיא דכל היכא דאמרינן את\"ל איפשיטא ההיא בעיא הוה ליה לפרש שאם לא היה בסעודה ראשונה אינה ספק אלא ודאי שלא הוקבע המום י\"ל שמ\"ש ואם חסר אחד מכל אלו הרי זה ספק לא קאי לסעודה ראשונה דכל שלא אכלה קודם סעודה ראשונה ודאי לא הוקבע המום ומפני כך כשכתב כיצד לא הזכיר לא סעודה ראשונה ולא שניה משום דאם לא היה קודם סעודה ראשונה אינה ספק כמ\"ש:",1,0],[3,1,"אין המומין פוסלין בעוף וכו'. בריש פרק ב' דתמורה (דף י\"ד) ופ\"ג דמנחות (דף כ\"ה) תמות וזכרות בבהמה ואין תמות וזכרות בעופות.",1,0],[3,1,"ומ״ש בד״א במומים קטנים אבל עוף שיבש גפו או נקטעה ידו או נסמית עינו או נקטעה רגלו אסור לגבי המזבח וכו'. משנה בפרק חטאת העוף (זבחים דף ס״ח) ובת״כ תמים זכר בבקר תמות וזכרות בבהמה ואין תמות וזכרות בעוף יכול שיבש גפו ושנסמית עינו ושנקטעה רגלו תלמוד לומר מן העוף ולא כל העוף.",2,0],[3,1,"ומ\"ש וכן אם נולד בו אחת מהטריפות וכו'. נתבאר בפרק שקודם זה דטעמא משום הקריבהו נא לפחתך וההוא טעמא שייך גם בעוף:",3,0],[3,2,"תורים קטנים פסולים וכו'. משנה בפ\"ק דחולין (דף כ\"ב) ופירש\"י תחלת הציהוב כשמתחילין להביא נוצה יפה צהובה סביב לצוארו פסולים בזה ובזה וכו' דבבני יונה פסולים משום גודלן ובתורים מפני קטנן דיצאו מכלל קטנים ולכלל גדולים לא באו.",1,0],[3,2,"ומ\"ש ועד מתי יהיו בני יונה כשרים כל זמן שעוקר כנף ומתמלא מקום עיקרו דם. שם מאימתי בני יונה כשרים וכו' מכי שמיט גדפא מיניה ואתי דמא ופירש\"י מאימתי בני יונה כשרים דביום שנולדו מאוסים הם ורבינו נראה שהיה גורס עד אימתי בני יונה כשרים ונראה שהיא הגירסא הנכונה.",2,0],[3,2,"ומ\"ש והתורים כשרים משיזהבו. שם ופירש\"י שיהיו כנפי גופם גדולים ואדומים ומזהיבים כזהב:",3,0],[3,3,"הטומטום והאנדרוגינוס וכו'. בסוף פרק על אלו מומין (בכורות דף מ״א) תנן דטומטום ואנדרוגינוס אין נשחטין לא במקדש ולא במדינה וחכמים אומרים אין מום גדול מזה.",1,0],[3,3,"ומה שכתב הרי הם פסולים למזבח מדרך אחרת וכו' לפיכך אף העוף שהוא טומטום או אנדרוגינוס פסול למזבח הכי אמרי' בפ' המזבח מקדש (זבחים דף פ״ה) דטומטום ואנדרוגינוס דעוף מטמאים כגריס בבית הבליעה כלומר אם מלקה ופירש רש״י אע״פ שלא נאמר תמות וזכרות בעופות קסבר בריה בפני עצמה היא ואינה ספק זכר ספק נקבה עכ״ל. ואע״ג דרבי אליעזר פליג עליה בפרק על אלו מומין פסק רבינו כתנא דסתם ברייתא ואע״ג דתניא בתורת כהנים העוף שלא נאמר בו זכר ונקבה אין טומטום ואנדרוגינוס פוסלין בו לא חש לה רבינו משום דס״ל דרבי אליעזר היא ולא קי״ל כוותיה. ומ״מ יש לדון על הטעם שכתב רבינו שהרי לא נאמר זכר תמים בעוף וצריך לומר דה״ק כיון שלמדנו בקרבנות שהטומטום והאנדרוגינוס מין אחר א״כ בעוף ג״כ הם מין אחר והתורה לא הכשירה מהעוף אלא תורים ובני יונה ואלו אינם לא תורים ולא בני יונה:",2,0],[3,4,"וכן הכלאים ויוצא דופן ומחוסר זמן וכו' עד פרט ליתום. בת\"כ.",1,0],[3,4,"ומ\"ש שנולד אחר שנשחטה אמו. משנה בפרק בתרא דבכורות (דף נ\"ז) איזהו יתום כל שמתה אמו או נשחטה ואחר כך ילדה ואיני יודע למה השמיט רבינו שמתה אמו:",2,0],[3,5,"הנדמה אע״פ שאינו כלאים וכו'. פרק יוצא דופן (נדה דף מ״א) ופרק שני דבכורות (דף י״ז).",1,0],[3,5,"ומ\"ש אע\"פ שיש בו מקצת סימנים וכו' שאין לך מום קבוע גדול מן השנוי. אע\"ג דתנן בפרק שני דבכורות (דף ט\"ז:) שאם יש בו מקצת סימנים חייב בבכורה הא אמרינן בריש מכילתין (דף ג':) בשם רבי יוחנן דמום קבוע הוי לישחט עליו ופירש\"י דהא דקתני חייב ליתנו לכהן קאמר אבל למזבח לא קרב דהאי דאישתני מום קבוע הוי לישחט עליו בחוץ והתוספות כתבו בפרק בתרא דכריתות בכל מקום רגיל לדלג נדמה כאילו הוא בכלל כלאים וזה דעת רבינו שכשמנה כל האסורים למזבח לקמן דילג נדמה:",2,0],[3,6,"וכן הרובע והנרבע והמוקצה לעבודה זרה וכו'. משנה וגמרא בתמורה פרק כל האסורים (תמורה דף כ״ח).",1,0],[3,6,"ומ\"ש וכן בהמה או עוף שהרגו את האדם הרי הם כרובע ונרבע ופסולים למזבח. במשנה ריש פרק התערובות (דף ע\"א:):",2,0],[3,7,"ויראה לי שאע״פ שאין כל הפסולים האלו וכו'. בפרק אותו ואת בנו (חולין דף פ':) גבי הא דתנן דשוחט אותו ואת בנו קדשים בפנים לוקה ופריך ולילקי נמי משום לאו דמחוסר זמן דתניא מנין לכל הפסולים שבשור ושבשה שהוא בלא ירצה תלמוד לומר ושור ושה שרוע וקלוט וגו' לימד על הפסולים שבשור ושבשה שהוא בלא ירצה כי קא חשיב לאו דאותו ואת בנו לאוי נוכראי לא קא חשיב וכו' ר' זירא אמר הנח למחוסר זמן שהכתוב נתקו לעשה מ״ט דאמר קרא מיום השמיני והלאה ירצה מיום השמיני אין מעיקרא לא לאו הבא מכלל עשה עשה וי״ל מאחר שמפורש בדברי רבי זירא דלא לקי למה תלה הדבר בעצמו שכתב ויראה לי ואין לומר דמשום דיש מחלוקת בדבר דלמאי דשני לאוי נוכראי לא קא חשיב לוקה הוא ובפרק בתרא דזבחים (דף קי״ד) אמרינן דלא אמר רבי זירא אלא לרבנן אבל לר״ש לקי מש״ה תלה הדבר בעצמו לומר שהוא פוסק כרבנן וכדרבי זירא דמה נשתנה דין זה משאר דינין שהוא מכריע בין המחלוקות וכותבם סתם ואינו תולה הדבר בעצמו ועוד יש לתמוה עליו למה תולה הדבר בשלא נתפרשה אזהרתן ואינו כן שהרי הגמרא אומרת נתפרשה אזהרתן ולא פטר מחוסר זמן אלא מפני שניתק לעשה ועוד שכל שאר פסולים חוץ ממחוסר זמן ילקה עליהם שהרי לא נתקן לעשה ומיהו בהא אפשר לומר שרבינו הוקשה לו דהא לא ירצה לא משמע דמזהר דלא יקריבוהו ולא לימד אלא שלא יעלה לרצון אבל אזהרה שלא יקריבנו אין כאן ולכך משמע ליה דה״מ לשנויי הכי אלא דלפום מאי דס״ד דמקשה דלא ירצה היינו להזהיר שלא יקריבוהו שני ליה אבל אפשר דאין כאן אזהרה מלהקריב כדאמרינן ומפני כך לא רצה רבינו לכתוב שהכתוב נתקו לעשה דהוה משמע דפשיטא ליה דלא ירצה הוי אזהרה שלא יקריבוהו אלא תלה הדבר בשלא נתפרשה אזהרתן לומר דאפשר דלא ירצה לא בא להזהיר שלא להקריב ואפילו את״ל שבא להזהיר שלא להקריב כיון שאינו מפורש שהרי אפשר שלא בא להזהיר שלא יקריבנו אלא לומר שלא יעלה לרצון אין ללקות מספק ויש סעד לדבריו דלקמן בסמוך כתב רבינו טעם פיטור מחוסר זמן ממלקות מפני שהוא לאו הבא מכלל עשה ולא כתב מפני שניתק לעשה כדרבי זירא משום דדילמא לא ירצה לא בא להזהיר שלא יקריבנו ואין כאן לאו לשנצטרך לומר שניתק לעשה:",1,0],[3,7,"אבל אתנן זונה ומחיר כלב וכו'. זה על הכלל הידוע בכמה מקומות בגמרא לאו שבכללות אין לוקין עליו ודברי רבינו בכאן ע\"פ דרכו בספר המצות שלו בשורש התשיעי בפירוש לאו שבכללות אין לוקין עליו אבל הרמב\"ן בהשגותיו חולק עליו ומפרש בע\"א:",2,0],[3,8,"מצות עשה להקריב כל הקרבנות מיום השמיני והלאה וכו' ואע\"פ שמחוסר זמן פסול אינו לוקה וכו'. נתבאר בסמוך:",1,0],[3,9,"תורים שלא הגיע זמנן וכו'. מחוסר זמן כבר נתבאר בסמוך שאינו לוקה עליו משום דלית ביה אלא לאו הבא מכלל עשה ותורים שלא הגיע זמנן ובני יונה שעבר זמנן לא לקי עלייהו מהאי טעמא דלית בהו לאו ולא שמעינן להו דפסולי אלא מדכתב והקריב מן התורים או מן בני היונה:",1,0],[3,10,"המקדיש טומטום ואנדרוגינוס וטריפה וכו' ואינן כבעל מום שבעל מום יש במינו קרבן. בסוף פרק שני דתמורה (דף י\"ז ע\"א) תנן רבי אליעזר אומר הכלאים הטריפה ויוצא דופן [וטומטום ואנדרוגינוס] לא קדושים ולא מקדישין וכתב רבינו בפירוש המשנה שדברי ר\"א אין עליהן חולק עכ\"ל. ואפילו אם היה עליהם חולק מאחר דאמוראי שקלי וטרי לפרושי מילתיה הוה משמע דהלכתא כותיה ואע\"ג דאתמר עלה בגמרא אמר שמואל לא קדושים בתמורה ולא מקדישין לעשות תמורה לא למעט ולומר שאם הקדישן בפה יהיו קדושים דאדרבה במכ\"ש אתיא וכן פירש\"י וז\"ל לא קדושים בתמורה ואע\"פ שהתמורה חלה קדושת הגוף על בעל מום קבוע אינה חלה על אלו וכל שכן שאין קדושת הגוף חלה עליה בהקדש הפה אלא קדושת דמים כעצים ואבנים ואינם צריכים מום ליפדות עכ\"ל.",1,0],[3,10,"ועל מ\"ש רבינו וימכרו ויביא בדמיהם כל קרבן שירצה כתב הראב\"ד מדקאמר ויביא בדמיהם כל קרבן שירצה וכו'. וי\"ל שמ\"ש",2,0],[3,10,"רבינו ואינם כבעל מום לא לענין קדישי ולא קדישי קאמר אלא לענין",3,0],[3,10,"מ\"ש ה\"ז כמקדיש עצים ואבנים קאי כלומר ואינו חייב מלקות ואתא למיהב טעמא אמאי לא מחייב מלקות כמו מקדיש בעלי מומין וקאמר דשאני התם שיש במינו קרבן. והם דברי רב פפא בגמרא:",4,0],[3,10,"אבל המקדיש רובע ונרבע וכו'. בר״פ כל האסורים (תמורה דף כ״ח) תניא הרובע והנרבע וכו' הם כקדשים שקדם מום עובר להקדשן וצריכים מום קבוע ליפדות עליהם:",5,0],[3,10,"וכן המקדיש מחוסר זמן וכו'. פשוט הוא:",6,0],[3,10,"כתב הראב\"ד ונרבע א\"א מ\"ט לא תני יתום שנולד אחר שנשחטה אמו עכ\"ל. ומשמע דקאי למה שכתב אבל המקדיש רובע ונרבע וכו' הרי זה כבעל מום עובר אמאי לא תני בהדייהו יתום והר\"י קורקוס ז\"ל תירץ דיתום הוי בכלל יוצא דופן דכיון שנולד אחר שנשחטה אמו אין זו לידה וכך אמרו פרק שני דחולין (דף ל\"ח:) [אי דמתה אימיה] והדר ילידתיה מכי יולד נפקא וכתב רש\"י דהיינו יוצא דופן ושם העמידו הפסוק בזה פירש למיתה וזה פירש לחיים ומשום דקי\"ל דא\"א לצמצם השמיטו רבינו:",7,0],[3,12,"כל האסורים לגבי המזבח וכו'. משנה בר״פ התערובות (דף ע':) ובתמורה ר״פ כל האסורים (תמורה דף כ״ח).",1,0],[3,12,"ומ״ש וכולם ולדותיהן מותרים. משנה בפרק כל האסורים (תמורה דף ל':):",2,0],[3,12,"ומ\"ש חוץ מולד נרבעת ונעבדת ומוקצת ושהמיתה את האדם. בפרק כל האסורים (שם:) אמר רבא ולד הנרבעת אסורה היא וולדה נרבעו ולד נוגחת אסורה היא וולדה נגחו ולד מוקצת ונעבד מותר מ\"ט לאימיה אקציה לאימיה פלחי לה איכא דאמרי ולד מוקצה ונעבד אסור מ\"ט דניחא ליה בניפחיה ופסק רבינו כלישנא בתרא:",3,0],[3,13,"ומ\"ש בד\"א בשנעבדה בה עבירה או שהמיתה כשהיתה מעוברת וכו' אבל אם נתעברה אחר שנעבדה בה עבירה או אחר שהמיתה הרי ולדה כשר למזבח. שם פלוגתא דאמוראי ופסק כרבא דאמר הכי.",1,0],[3,13,"ומ\"ש אפילו נרבעת כשהיא מוקדשת ואחר כך נתעברה וכו'. שם מימרא דרב נחמן ואית בה תרי לישני ופסק כלישנא קמא וכתב הר\"י קורקוס ז\"ל דטעמא דכיון דלא הוי אלא משום ביזוי אזלינן לקולא ותו דרבא דמוקי פלוגתייהו בזה וזה גורם משמע דלא מפליג מידי דהא לא קאמר דמודו אלא היכא דהיא וולדה נגחו ונרבעו וכל השאר זה וזה גורם הוא ומותר ולא מפלגינן מידי וזה ברור עכ\"ל.",2,0],[3,13,"ומ\"ש וכן אפרוח ביצת טריפה מותר למזבח. ברייתא שם:",3,0],[3,14,"המשתחוה לקמה חטיה מותרים למנחות וכו'. בעיא בפרק כל הצלמים (עבודה זרה דף מ״ו:) ובעא מר זוטרא בריה דרב למפשטה מדתנן כל האסורים למזבח ולדותיהם מותרים כלומר וקמח למנחות דמי לולדות ואע״ג דדחי ליה התם מדאמר רב נחמן עיברו ולבסוף נרבעו ד״ה אסורים הא אסיקנא התם הכי השתא התם מעיקרא בהמה והשתא בהמה דשא הוא דאחיזא באנפה הכא מעיקרא חיטי והשתא קמחא:",1,0],[3,14,"וכן בהמה שפטמה וכו'. ס״פ כל האסורים (תמורה דף כ״ט):",2,0],[3,15,"לוקחין כל הקרבנות מהעכו\"ם וכו'. ברייתא בריש פרק שני דעבודה זרה (דף כ\"ב:):",1,0],[4,1,"אחד הבהמה ואחד העוף וכו'. נתבאר בפרק שקודם זה ולגבי עוף בפרק המזבח מקדש (זבחים דף פ״ה:) בעי ר' ירמיה אם יש נרבע בעופות ופשטינן ממתני' דיש נרבע בעופות אמר רב נחמן בר יצחק אף אנן נמי תנינא הנרבע והמוקצה והנעבד ואתנן ומחיר וטומטום ואנדרוגינוס כולם מטמאים בגדים בבית הבליעה שמע מינה:",1,0],[4,2,"הרובע והנרבע ושהמית את האדם וכו'. במשנה בריש פרק התערובות (דף ע') ובפ\"ו דתמורה (דף כ\"ח):",1,0],[4,2,"ומ\"ש היה שם עד אחד וכו'. בקידושין פרק האומר (דף ס\"ה ס\"ו) אמר אביי אמר לו עד אחד שורך נרבע והלה שותק נאמן ותנא תונא וכו' ומשמע טעמא מפני שהבעל שותק הא אם היה מכחיש אין העד נאמן:",2,0],[4,3,"בהמה ששחקו בה והגיחוה עד שהמיתה את האדם וכו'. בפרק שור שנגח ד' וה' (בבא קמא דף מ':) פלוגתא דרב ושמואל ופסק כרב דהלכה כוותיה באיסורי:",1,0],[4,3,"אין הבהמה נפסלת משום רובע וכו'. כתב הראב״ד זה המחבר דימה איסור מזבח וכו'. מ״ש ומתניתין היא בנדה הוא בפרק יוצא דופן (נדה דף מ״ה).",2,0],[4,3,"ומ\"ש ואולי אין מדמין שהרי נרבע על פי הבעלים או ע\"פ עד אחד שאינו במיתה ופסול למזבח י\"ל דשאני התם שהביאה היתה ביאה ואע\"פ שלא נודע הדבר בשני עדים כיון שנודע על פי עד אחד והבעל שותק מהימנינן ליה ליפסל מעל גבי המזבח אבל כשהנרבע פחות מכשיעור אפילו יש שני עדים בדבר אין כאן ביאה כלל וכיון שכן אין כאן נעבדה בה עבירה ואפילו אם תימצי לומר שהרובע נהנה לא מיפסלא משום הכי כיון שאין כאן ביאה דהוי ליה כמעשה חידודין דאע\"פ ששניהם נהנים לא מיחייבי מיתה ולא מיפסלי מעל גבי המזבח. ומה שלא הזכירו בפרק יוצא דופן כשהבהמה רובעת לפחות משלש שנים משום דהיא מילתא דלא שכיחא כלל:",3,0],[4,4,"מאימתי תפסל הבהמה או העוף וכו'. בתמורה בפרק כל האסורים (תמורה דף כ״ט) א״ר יצחק אין מוקצה אסור עד שיעבדו ופירש״י עד שיעבדו בו שום עבודה לצורך עבודה זרה או משיכת קרון או שום דבר אבל מקמי הכי לא מיתסרי. וכתב הראב״ד יש בספרים שלנו נוסחא אחרינא וכו' ונוסחא זו שכתב הראב״ד רש״י הזכירה גם כן ודברי רבינו כנוסחא האחרת והתוס' מכריע כדברי רבינו ומכל מקום קשיא לי על רבינו למה פסק כרב יצחק כיון דפליגי עליה דאמרי' עלה עולא א״ר יוחנן עד שימסרוהו למשרתי ע״ז בהא א״ר יוחנן עד שיאכילוהו כרשיני עבודה זרה אמר ליה רבי אבא לבהא מפלגיתו אתון אעולא אמר ליה לא עולא נמי כי קאמר הוא דספי ליה כרשיני עבודה זרה ומאחר דרבי יוחנן פליג אדרב יצחק הוה ליה למיפסק כרבי יוחנן ויש לומר דבתר הכי אמרי' תני רב חנניה טריטאה קמיה דרבי יוחנן אין מוקצה אסור אלא עד שיעשו בו מעשה הוא תני ליה והדר אמר לה מאי מעשה עד שיגוזו ויעבדו בו וכיון דרב יצחק אתי כתני קמיה דרבי יוחנן פסק הכי ולא חש לעולא ולבהא ועוד דהא דתני קמיה דר' יוחנן ברייתא היא בתוספתא פרק ששי ואיכא למימר דבתר דאמר רבי יוחנן לדעולא ולדבהא שמעה להאי ברייתא הדר ביה ומשום הכי שתיק כי תנא קמיה דקבלה מיניה:",1,0],[4,4,"ומ\"ש רבינו שאין הקדש לע\"ז. בתוספתא הנזכרת מסיים אבל אמר שור זה לעבודה זרה ובית זה לעבודה זרה לא אמר כלום שאין הקדש לע\"ז:",2,0],[4,5,"הרובע והנרבע בין שהיתה הבהמה שלו בין של חבירו וכו' אבל המוקצה אם היה שלו וכו' הנעבד בין שעבד שלו בין של חבירו וכו' עד הרי זה אסור. הכל בתוספתא דתמורה פ' רביעי אלא שמה שאמר רבינו שאם הקצה אחר הקדשו מותר לא מצאתיו בתוספתא בנעבד כתוב באונס כשר ואפשר שחסרון וטעות סופר יש בתוספתא שבידינו:",1,0],[4,6,"וכתב הראב\"ד בין שעבד שלו בין שעבד של חבירו א\"א במסכת ע\"ז פרק ררב ישמעאל (דף נ\"ד) אוקמוה בשל חבירו בשעשה בה מעשה עכ\"ל. ולדעת רבינו י\"ל דהתם לאסרה להדיוט אבל לגבוה אף על פי שלא עשה בה מעשה נאסרה וכדתנן פרק כל האסורים גבי מוקצה ונעבד שאסורים למזבח זה וזה מותרים באכילה וכבר כתבתי שדברי רבינו הם דברי התוספתא: והנעבד הוא וכל מה שעליו אסורים למזבח וכו'. משנה בריש פרק כל האסורים שם איזהו מוקצה המוקצה לעבודה זרה הוא אסור ומה שעליו מותר ואי זהו הנעבד כל שעובדים אותו הוא ומה שעליו אסור זה וזה מותרים באכילה.",1,0],[4,6,"ומה שכתב שכל ציפוי נעבד אסור בהנאה מפורש שם מדכתיב לא תחמוד כסף וזהב עליהם וכו'.",2,0],[4,6,"ומה שכתב רבינו אסורים למזבח דמשמע אבל לא להדיוט אנעבד גופיה קאי דאילו מה שעליו אף להדיוט אסור בהנאה:",3,0],[4,7,"המשתחוה להר וכו'. בפרק כל הצלמים (עבודה זרה דף מ״ו) בעיא דאיפשיטא.",1,0],[4,7,"ומ\"ש המשתחוה למעיין הנובע בארצו הרי מימיו פסולין לנסך. שם (דף מ\"ז) בעיא דלא איפשיטא וספיקה לחומרא. כתב הר\"י קורקוס ז\"ל בשם התוספות שנובע בארצו ואינו מתפשט לחוץ שאם מתפשט לחוץ הא אמרינן במרובה מעיין היוצא בתחלה בני העיר מסתפקים אם כן מים של רבים הם ואינם נאסרים ולכך לא כתב רבינו מארצם במ\"ם כלשון הגמרא עכ\"ל.",2,0],[4,7,"ומה שכתב אשרה שבטלה אין מביאין ממנה גיזרין למערכה. שם בעי ר\"ל המשתחוה לדקל לולבו מהו למצוה כי אתא רב דימי אמר באשירה שביטלה קא מבעי' ליה ולא איפשיטא ולחומרא וכיון דלענין לולב למצוה מספיקא פסלינן לה מכ\"ש דפסלינן לה לגיזרין למערכה.",3,0],[4,7,"ומ\"ש וכן המשתחוה לבהמה כשם שנפסלה למזבח צמר שלה פסול לבגדי כהונה וקרניה פסולים לחצוצרות וכו' עד ובני מעיה לנימין. שם בעיי דלא איפשיטו ולחומרא. ודע דהתם בעי בהאי לישנא צמרה מהו לתכלת וקא מתמה תכלת דמאי אי דכהנים היינו דרמי בר חמא ופירש\"י תכלת דכהנים דבגדי כהונה לצורך עבודה וקא מיבעיא לן מכשירי קרבן כקרבן דמו או לא ואת\"ל כקרבן דמו היכא דנשתנה כשצובעין אותו יש שינוי בנעבד להתירו לגבוה או לא. היינו בעיא דרמי בר חמא דהיינו תרתי בעיי דבעא רמי בר חמא לעיל עכ\"ל. ובעיא דרמי בר חמא היא במשתחוה לקמה חטיה מהו למנחות יש שינוי בנעבד או לא ופשטינן דיש שינוי לנעבד ומותר וכן פסק רבינו בס\"פ שקודם זה וא\"כ ה\"ל למיפסק דלבגדי כהונה כשר מאחר דאישתני לכך נ\"ל שרבינו מפרש דלא דמיא למשתחוה לקמה דהתם שינוי גמור הוא דמעיקרא חיטי והשתא קמחא אבל הכא דמעיקרא צמר והשתא צמר אע\"ג דמעיקרא לבן והשתא תכלת לאו שינוי גמור היא ולא קאמר היינו דרמי בר חמא אלא משום בעיא דמשתחוה להר אבניו מה הן למזבח דאמרינן דמיבעי' ליה אי מכשירי קרבן כקרבן דמו או לא:",4,0],[4,8,"אי זהו אתנן האומר לזונה הא ליך דבר זה בשכריך. משנה בפרק כל האסורים (תמורה דף כ״ט).",1,0],[4,8,"ומה שכתב אחד זונה כותית וכו' או ישראלית. שם פלוגתא דאביי ורבא בזונה ישראלית ופסק כרבא.",2,0],[4,8,"ומ\"ש שפחה. מתבאר שם במשנה האומר לחבירו הא לך טלה ותלין שפחתך אצל עבדי וכמו שיבוא בפרק זה.",3,0],[4,8,"ומ\"ש שהיא ערוה עליו. שם.",4,0],[4,8,"ומ\"ש או מחייבי לאוין. שם כגון אלמנה לכהן גדול ואליבא דרבא מיתוקמא כרבנן דפליגי אר\"ע וסברי דקידושין תופסין בחייבי לאוין.",5,0],[4,8,"ומ\"ש אבל הפנויה אפי' היה כהן אתננה מותר. שם לאפוקי מרבי אלעזר דאמר פנוי הבא על הפנויה שלא לשם אישות עשאה זונה כלומר והרי היא אסורה לכהן.",6,0],[4,8,"ומ\"ש וכן אשתו נדה אתננה מותר אף על פי שהיא ערוה. שם פלוגתא דרב ולוי ופסק כרב ואיני יודע למה ואדרבה משמע בגמרא דלית הלכתא כוותיה דאמרינן ורב האי תועבה מאי עביד ליה מיבעי ליה לכדאביי דאמר זונה כותית אתננה אסור וכו' וכיון דלא קיימא לן כאביי אלא כרבא וכמו שפסק רבינו לעיל בסמוך היאך פסק כרב ואפשר שטעמו משום דרבי סבר הכי ואע\"ג דאמרי' דרב מיבעי ליה לכדאביי לאו דוקא דלדידן דלא קי\"ל כאביי נימא דלרב תועבה אתא לרבות הזכור:",7,0],[4,9,"נשא אחת מחייבי לאוין וכו'. נראה שטעם רבינו דמשמע ליה דכי אוקימנא אליבא דרבא כגון אלמנה לכ\"ג וכרבנן דתופסין בה קידושין אפילו בקידשה ונשאה מיתוקמא:",1,0],[4,9,"והזכור אתננו אסור. מימרא בפרק כל האסורים.",2,0],[4,9,"ומ\"ש נתנה האשה אתנן לבועל הרי זה מותר משום אתנן. שם: ודע דתניא תו התם אם נתן לה שכר הפקעתה מותר ופירש\"י שכר הפקעתה שכר מה שביטלה ממלאכתה ולא שכר ביאה ולא ידעתי למה השמיטו רבינו:",3,0],[4,10,"האומר לחבירו הא לך דבר זה וכו'. משנה שם האומר לחבירו הילך טלה זה ותלין שפחתך אצל עבדי רבי [מאיר] אומר אינו אתנן וחכמים אומרים אתנן ובגמרא (דף ל') שפחה לעבד מישרא שרי ואסיקנא בעבד עברי וטעמייהו דרבנן משום דהב\"ע כשאין לו אשה ובנים.",1,0],[4,10,"ומ\"ש וה\"ה באומר לזונה הא ליך דבר זה והבעלי לפלוני הישראלי הרי זה אתנן. ק\"ל דפשיטא ובמכ\"ש אתיא מעבד שאינו חייב בכל המצות כמו הישראלי וי\"ל דה\"א שאני התם שהוא עבדו קמ\"ל:",2,0],[4,11,"פסק עם הזונה ליתן לה טלה אחד ונתן לה הרבה וכו'. משנה וגמרא שם וקמ\"ל דלא תימא מתנה היא דיהיב לה אלא כולהו מכח אתנן אתו:",1,0],[4,11,"נתן לה אתננה ולא בא עליה וכו' (עיין בפנים). כך היא הגירסא הנכונה בדברי רבינו ודינים אלו בפרק כל האסורים (שם) נתן לה ואחר כך בא עליה אתננה מותר וליחול עלה אתנן למפרע א\"ר אלעזר שקדמה והקריבתו ה\"ד אי דאקנייה ניהלה לאלתר פשיטא דמותר וכו' ואלא דאמר לה לא נקני לך עד שעת ביאה מי מציא מקרבה ליה כי יקדיש את ביתו קדש לה' אמר רחמנא מה ביתו ברשותו אף כל ברשותו לא צריכא דאמר ליה לא ניקני ליך עד שעת ביאה ואי מצטריך ליך ניקני לך מעכשיו:",2,0],[4,12,"ומ\"ש קדמה והקדישתו וכו'. שם בעיא דלא איפשיטא:",1,0],[4,13,"בא עליה ולא נתן לה ולאחר זמן נתן לה וכו'. שם בא עליה ואחר כך נתן לה אתננה מותר והא תניא בא עליה ונתן לה אפילו עד י\"ב חדש אתננה אסור וכו' ל\"ק הא דא\"ל הבעלי לי בטלה זה הא דא\"ל הבעלי לי בטלה סתם טלה זה והא מחוסר משיכה בזונה כותית דלא קניא במשיכה ואיבעית אימא אפי' בזונה ישראלית כגון דקאי בחצירה הא יהיב לה מעיקרא דשויא לה אפותיקי ואומר לה אם עד יום פלוני יהיבנא לך זוזי מוטב ואם לא טלה באתננך ופירש\"י בטלה זה הואיל דיהביה בשעת ביאה חייל עליה אתנן מיד. טלה סתם דמשדר לה בתר הכי מתנה בעלמא הוא ואין אתנן אלא המיוחד בשעת ביאה. הא יהביה ניהלה מעיקרא דהואיל וקאי בחצירה קניא ליה בשעת ביאה מיד ואמאי קרי ליה ואחר כך נתן ועוד פשיטא וכו'. עד יום פלוני משקלין לך כך וכך ואי לא שקלי ליה הילכך מטי ולא יהיב לה זוזי איגלאי מילתא דאדידיה הואי ביאה ומיהו אח\"כ הוא דהא לא הוי דידה עד דמטי יום פלוני ואיצטריך לאשמועינן דאסור עכ\"ל. ולשון רבינו שכתב שאינה צריכה משיכה אינו מכוון עם לשון הגמרא שאמרה בזונה כותית דלא קניא במשיכה וטעם רבינו מפני שהוא סבור יד עכו\"ם קונה בין בכסף בין במשיכה כמבואר בדבריו בפ\"א מה' זכיה ולפי זה ע\"כ לפרש בהאי דלא קניא במשיכה פירושו דלא צריכה משיכה דבכסף בלחוד קניא והביאה היא במקום כסף והילכך זונה ישראלית שאינה קונה בכסף בלא משיכה אינו אתנן אבל זונה כותית שאין צריך משיכה לקניינה הוי אתנן:",1,0],[4,14,"אין אסור משום אתנן ומחיר וכו' נתן לה מעות ולקחה בהם קרבן הרי זה כשר. משנה שם (דף ל').",1,0],[4,15,"נתן לה חטים ועשאתן סולת וכו'. שם ב\"ש אוסרים וב\"ה מתירים:",1,0],[4,15,"נתן לה בהמת קדשים באתננה לא נאסרה למזבח. משנה שם.",2,0],[4,15,"ומ\"ש ואפילו מנה אותה על פסחו וחגיגתו באתננה לא נפסלו המוקדשין וכו'. שם אהא דממעט מוקדשין מדכתיב לכל נדר להוציא את הנדור ומקשה טעמא דמעטינהו קרא הא לא מעטינהו קרא ה\"א כי יהיב לה מוקדשין חל עליהם אתנן ומחיר והא לאו ממוניה הוא אמר רב הושעיא בממנה על פסחו ורבי היא וכו' [דאמר] אם אין לו ממנה אחרים עמו על פסחו ועל חגיגתו ומעותיו חולין ופסק רבינו בהלכות קרבן פסח פ\"ד הלכה כרבי.",3,0],[4,15,"ומ\"ש רבינו שכבר זכה בהם גבוה משעה שהקדישן. היינו לומר דאע\"ג דהממנה אחרים עמו על פסחו המעות חולין וא\"כ כשמנה את זו על פסחו באתננה היה ראוי ליפסל לא נפסל מפני שמשעה שהקדישו זכה בו גבוה ואימעיט מדין אתנן מלכל נדר להוציא את הנדור:",4,0],[4,15,"וכן אם נתן לה דבר שאינו שלו לא פסלו וכו'. נלמד ממה שכתבתי בסמוך שאמרו והא לאו ממוניה הוא:",5,0],[4,15,"אבל אם נתן לה עופות וכו'. שם תנן נתן לה מוקדשים הרי אלו מותרים עופות הרי אלו אסורים שהיה בדין מה אם המוקדשין שהמום פוסל בהם אין אתנן ומחיר חל עליהם עופות שאין המום פוסל בהם אינו דין שלא יהא אתנן ומחיר חל עליהם תלמוד לומר לכל נדר להביא את העוף.",6,0],[4,15,"ועל מה שכתב אפילו הם מוקדשים כתב הראב\"ד לא כן אנו מקובלים וכו'. ואני תמה על הראב\"ד היכי שבקיה לרגזנותיה שלא כתב בדרך השגה והיא קושיא חזקה שא\"א לומר שנתרבו עופות לאיסור אתנן אפילו הם מוקדשין וכשנתמעטו מוקדשין מאיסור אתנן חוץ ממוקדשי עוף הוא שנתמעטו דהא עופות לא בהדיא נתרבו כי היכי דתימא דנתרבו אפילו הם מוקדשין דלא איתרבו אלא מלכל נדר וא\"כ כי ממעטינן נדור עופות נדור נמי ממעטינן ועוד דמוקדשין א\"א בשום פנים לחול עליהם איסור אתנן דהא לאו ממוניה הוא כדמקשה גמרא. ובעל מגדל עוז תירץ דמאי אע\"פ שהם מוקדשין דקאמר הרמב\"ם שהם ראויים להיות מוקדשין כלומר תורים ובני יונה וכל שכן אווזים ותרנגולים שאינם ראויים להיות מוקדשין שאתנן חל עליהם ואסורים עכ\"ל ופירוש דחוק הוא ביותר. ואפשר לומר דמאי אע\"פ שהם מוקדשים דקאמר רבינו אע\"פ שהקצה להקריבן אבל עדיין לא הקדישן בפה.",7,0],[4,15,"ומ\"ש רבינו ומדברי קבלה הוא דבר זה:",8,0],[4,16,"אי זהו מחיר כלב וכו'. משנה שם (דף ל') ופשוט הוא.",1,0],[4,16,"ומ\"ש וכן אם החליף כלב בכמה בהמות או עופות וכו'. פשוט הוא:",2,0],[4,17,"שני שותפים שחלקו וכו'. משנה שם שני שותפין אחד נטל עשרה ואחד [נטל] ט' וכלב שכנגד הכלב אסור ושעם הכלב מותר ובגמרא ניפוק חדא להדי כלבא והנך כולהו לישתרו הב\"ע כגון דטפי דמי כלב מחד מינייהו והאי טופיינא דכלב שדי בכולהו:",1,0],[4,18,"נשתנה המחיר וכו'. ברייתא שם גבי אתנן וב\"ה מתירים משום דכתיב שניהם הם ולא שינוייהם ועוד דרשו שם הם ולא ולדותיהם ולא ידעתי למה השמיטו רבינו:",1,0],[4,18,"אתנן כלב ומחיר זונה מותרים. משנה שם.",2,0],[4,18,"ומ\"ש אתנן זונה ומחיר כלב מותרים לבדק הבית שהרי הם משתנים. זה פשוט שאפי' למזבח שינוייהם מותרים.",3,0],[4,18,"ומ\"ש אבל גופן לא יעשה ריקועים לבית וכו'. שם תנו רבנן בית ה' אלהיך פרט לפרה שאין באה לבית דברי ר' אלעזר וחכמים אומרים לרבות את הריקועים ופסק כחכמים ואע\"ג דאמר רב חסדא מאן חכמים רבי יוסי ברבי יהודה מכל מקום כיון דתנא דברייתא שנאו בלשון חכמים הכי נקטינן ועוד דבפרק שני דמסכת פרה (משנה ג') שנינו אתנן ומחיר פסולה ר' אלעזר מכשיר הרי ששנה דברי החולק על רבי אלעזר בסתם אלמא לית הלכתא כרבי אלעזר:",4,0],[5,1,"שאור ודבש אסורים לגבי מזבח וכו'. בת״כ כי כל שאור וכל דבש לא תקטירו אין לי אלא מרובה מניין אפילו מועט ת״ל כל. ודע דבפרק כל המנחות (מנחות דף נ״ח) ת״ר שאור בל תקטירו אין לי אלא כולו מקצתו מנין ת״ל כי כל מאי קאמר אמר אביי ה״ק שאור בל תקטירו אין לי אלא כזית חצי כזית מנין ת״ל כל [עירובו מנין ת״ל כי כל] רבא אמר ה״ק שאור בל תקטירו אין לי אלא קומץ חצי קומץ מנין ת״ל כל וכו' במאי קא מיפלגי אביי סבר יש קומץ פחות משני זיתים [ויש הקטרה פחותה מכזית ורבא אמר אין קומץ פחותה מב' זיתים] ואין הקטרה פחותה מכזית ומשמע דרבא דפליג אאביי ודריש דרשא דכל לחצי קומץ סבר דלא מיחייב על שאור ודבש בפחות מכזית כשאר איסורין דהא לית ליה קרא לחיובי בכחצי זית וא״כ יש לתמוה למה פסק רבינו כאביי ודלא כרבא. ועוד שכתב לקמן בסמוך ואין הקטרה פחותה מכזית והיינו כרבא וזה סותר מ״ש כאן. ואפשר שרבינו מפרש דרבא לא פליג אאביי דדריש מכל לרבויי חצי זית דשאור ודבש אלא שמוסיף לדרוש נמי לחצי קומץ דתרוייהו משתמע.",1,0],[5,1,"ומ\"ש ואין הקטרה פחותה מכזית היינו בתערובות וצריך שיהא כזית אע\"פ שאין בו אלא כל שהוא משאור ודבש לוקה.",2,0],[5,1,"ומ\"ש ואינו חייב אלא אם הקטירן עם הקרבן או לשם קרבן יתבאר בסמוך.",3,0],[5,1,"ומ\"ש ואחד המקטיר עצמן או המקטיר תערובות שלהם לוקה. ברייתא בפרק כל המנחות.",4,0],[5,1,"ומ״ש לוקה על כל אחד מהם בפני עצמו ואם הקטיר שניהם כאחד אינו לוקה אלא אחת. בפרק כל המנחות (מנחות דף נ״ח:) פלוגתא דאביי ורבא והלכה כרבא דאמר לאו שבכללות אין לוקין עליו ודברי רבינו כאן הם ע״פ דרכו בסה״מ שלו בשורש הט' בפירוש לאו שבכללות אין לוקין עליו והרמב״ן בהשגותיו חולק עליו ומפרש בע״א. והראב״ד כתב א״א בספרים שלנו רבא מחייב שתים וארבע וכו' ואני אומר שגם גירסת ספרינו כגירסת הראב״ד אבל גירסת רבינו יותר נכונה משום דסוגיין דגמרא דאין לוקין על לאו שבכללות ואם כגירסת הראב״ד היה לנו לומר דלוקין כרבא שאין זו מיע״ל קג״ם דהלכה בהו כאביי:",5,0],[5,2,"נפל מהם כל שהוא בקטרת נפסלה. בברייתא דפיטום הקטרת פ\"ק דכריתות (דף ו') תניא אם נתן בה דבש פסלה ומשמע דהיינו מדכתיב לא תקטירו וא\"כ אין חילוק בין שאור לדבש ולא נקט תנא דבש אלא משום דמעלי לקטורת וכדקתני התם אם היה נותן קורטוב דבש אין אדם יכול לעמוד מפני ריחה ומפני מה אין נותנין בה דבש משום שנאמר כל שאור וכל דבש לא תקטירו.",1,0],[5,2,"ומ\"ש ואם הקטיר ממנה בהיכל לוקה. נראה שהטעם מפני שעבר בבל תקטירו.",2,0],[5,2,"ומ\"ש בהיכל מפני שהקטרת הקטורת בכל יום במזבח הזהב שהיה בהיכל ואינו עובר משום מקטיר דבש בקטורת אלא כשמקטיר במקום המיוחד לו אבל הקטיר חוץ מההיכל אינו עובר משום מקטיר דבש.",3,0],[5,2,"ומ\"ש ואין הקטרה פחותה מכזית. כרבא דאמר הכי כמ\"ש בראש פרק זה:",4,0],[5,4,"העלה שאור או דבש בפני עצמן למזבח לשם עצים פטור וכו'. בפרק התערובות (דף ע\"ו) אהא דתניא התם למחרת מביא אשמו ולוגו ואומר אם של מצורע ה\"ז אשמו וזה לוגו וכו' ומקשה והא בעי הקטרה ומשני דאקטיר ליה ומקשה אימתי אי בתר מתנות שבע הוה ליה שירים שחסרו וכו' אי קודם מתנות שבע כל שממנו לאישים הרי הוא בבל תקטירו אמר רב יהודה בריה דר\"ש בן פזי דמסיק להו לשם עצים דתניא רבי אליעזר אומר לריח ניחוח אי אתה מעלה אבל אתה מעלה לשום עצים ופרש\"י בל תקטירו דכתיב כי כל שאור וכל דבש לא תקטירו ממנו אשה לה' והאי ממנו יתירא הוא ודרשינן ביה נמי לא תקטירו כל שממנו אשה לה' בכלל הזה קדשים ושירי מנחה ולחם הפנים שקרב מהם כבר לאישים האמורים [וכן הקומץ] וכן הבזיכים קיימי שירים בבל תקטירו וכו'. לריח ניחוח אי אתה מעלה בתר ההוא קרא דכל שממנו לאישי' כתיב קרבן ראשית תקריבו אותם ואל המזבח לא יעלו לריח ניחוח קרבן ראשית אשאור ודבש הכתוב בראש המקרא העליון קאי וקאמר יש לך להביא מהם בכורים מהדבש ושתי הלחם מהשאור ואל המזבח לא יעלו אכוליה קרא קאי ואדרשא דבל תקטירו דשירים עכ\"ל.",1,0],[5,4,"ומ״ש אפי' הקטיר דבר שאינו ראוי להקטרה בדבש או בשאור הואיל והוא מן הקרבן לוקה כיצד המעלה מבשר חטאת ואשם וכו'. בפרק כל המנחות (מנחות דף נ״ז:) ת״ר מנין למעלה מבשר חטאת ומבשר אשם ומבשר קדשי קדשים ומקדשים קלים וממותר העומר וממותר שתי הלחם ומלחם הפנים ומשירי מנחות שהוא בלא תעשה ת״ל כי כל שאור וכל דבש לא תקטירו ממנו אשה ליי' כל שממנו לאישים הרי הוא בבל תקטירו עכ״ל:",2,0],[5,4,"וכתב הראב\"ד על דברי רבינו בחיי ראשי נשתבש בלשון הברייתא וכו'. ויש לתמוה על הראב\"ד היאך משוי לרבינו טועה לומר שהוא סבור שאינו חייב על שאור ודבש אא\"כ יש עמהם צד קרבן וח\"ו מלטעות רבינו בזה והרי דבריו מבוארים בראש הפרק שכתב ואינו חייב אלא אם הקטירן עם הקרבן או לשם קרבן ומדכתב תיבת או המבדלת משמע בהדיא דבהקריבן בפני עצמן לשם קרבן חייב לאפוקי שאם העלה אותם בפני עצמן לשם עצים פטור כמו שנתבאר בסמוך ואם העלם עם הקרבן חייב בכל גווני אפי' העלה השאור והדבש לשם עצים וזה מבואר בדבריו שכתבתי בסמוך אם הקטירן עם הקרבן או לשם קרבן דהיינו לומר אם הקטירן עם הקרבן אפילו הקטירן לשם עצים כיון דאיכא קרבן בהדייהו חייב או אם הקטירן לשם קרבן אפילו הקטירן לבדם חייב והשתא קאמר דכשהקטירם לשם עצים דאמרן שאם הקטירן עם הקרבן חייב לא מיבעיא אם הקטירן עם חלק מהקרבן הראוי להקטרה אלא אפי' הקטירם עם חלק מהקרבן שאינו ראוי להקטרה כגון בשר חטאת ובשר אשם וכו' חייב כיון שהם קרויים קרבן אבל אי קשיא בדברי רבינו הא קשיא כיון דהאי דרשא דכל שהוא ממנו לאישים הרי הוא בבל תקטירו מידריש בלא הקטירם עם שאור ודבש כדאיתא בפרק התערובות שכתבתי בסמוך וכתבו רבינו לקמן בסמוך א\"כ מנא ליה למדרשיה להקטירם עם שאור ודבש ואע\"ג דאיכא למימר דמשמע לרבינו דברייתא דמנין למעלה מבשר חטאת ומבשר אשם וכו' במקטירם עם שאור ודבש היא מדקבעה הגמרא בר\"פ כל המנחות באות מצה דעסיק בדיני הקרבת שאור אימתי חייב אכתי איכא למיבעי מנא ליה לגמרא למימר הכי וי\"ל דמשמע ליה לגמרא דאי דרשא דכל שהוא ממנו לאישים הרי הוא בבל תקטירו לא אתיא אלא להקטירם בלא שאור ודבש בלבד היא לא הו\"ל למכתביה גבי שאור ודבש ומדכתביה גבייהו משמע דאף במקטירם עם שאור ודבש היא וא\"ת אכתי אימא דלא אתא אלא להקטירם עם שאור ודבש ולא להקטירם בלא שאור ודבש וא\"כ ההיא דפ' התערובות מנ\"ל וי\"ל דא\"כ לכתוב קרא לא תקטירו אשה ממנו ומדכתב ממנו אשה משמע למדרש כל שממנו לאישים הרי הוא בבל תקטירו אפי' אין עמו שאור ודבש. ועדיין יש לדקדק דא\"כ כשהקטיר שאור ודבש אפי' לשם עצים עם חלק מהקרבן שאינו ראוי להקטרה ילקה שתים משום שאור ודבש ומשום כל שממנו לאישים וכההיא דפרק התערובות ומדברי רבינו לא משמע דלקי אלא אחת ואין לומר דטעמא דמשום דהוי לאו שבכללות שאינו לוקה על שניהם אלא אחת לדעתו ז\"ל שהרי כתב בסמוך וכן אסור להקטיר על המזבח מכל דברים אלו שאינם ראויים להקטרה ולא כתב שלוקה ואפשר לומר שסובר רבינו שעיקר הלאו למקטיר שאור ודבש עם חלק מהקרבן שאינו ראוי להקטרה ולקי עליה ומדלא כתב אשה ממנו דרשינן דהוא הדין להקטיר דבר שממנו לאישים בלא שאור ודבש לדרשא בעלמא אבל לא ללקות עליו כיון דעיקר קרא לאו להכי אתא.",3,0],[5,4,"ומ\"ש רבינו חטאת העוף וכו' ולוג שמן של מצורע. בפרק כל המנחות (דף כ\"ח) בעי רמי בר חמא מרב חסדא המעלה מבשר חטאת העוף על המזבח מהו כל שממנו לאישים אמר רחמנא והאי אין ממנו לאישים או דילמא כל ששמו קרבן והאי נמי שמו קרבן א\"ל כל ששמו קרבן והאי נמי שמו קרבן וכו' כתנאי ר\"א אומר כל שממנו לאישים רב עקיבא אומר כל ששמו קרבן מאי בינייהו אמר רב חסדא בשר חטאת העוף איכא בינייהו רב אמר לוג שמן של מצורע איכא בינייהו ופירש\"י כל ששמו קרבן אמר רחמנא דלא יקטירו משיריו דהכי כתיב בתר דההוא קרא קרבן ראשית ומקרא נדרש לפניו. עוף שמו קרבן דכתיב ואם מן העוף עולה קרבנו. לוג שמן של מצורע אין ממנו לאישים אבל קרבן איקרי כדאמרינן באלו מנחות לכל קרבנם לרבות לוג שמן של מצורע ובגופיה נמי כתיב והקריב אותו ואת לוג השמן עכ\"ל ופסק רבינו כר\"ע.",4,0],[5,4,"ומ\"ש רבינו המעלה כזית מאחת מאלו בחמץ או בדבש בין למזבח בין לכבש לוקה. שם אברייתא שכתבתי לעיל מנין למעלה מבשר חטאת מבשר אשם וכו' איתמר המעלה מכולם על הכבש רבי יוחנן אמר חייב דתניא מזבח אין לי אלא מזבח כבש מנין ת\"ל ואל המזבח לא יעלו לרצון ורבי אלעזר אמר פטור מ\"ט דאמר קרא שאור ודבש קרבן ראשית תקריבו אותם אותם הוא דרבי לך כבש כמזבח אבל מידי אחרינא לא ופסק רבינו כרבי אלעזר דגבי המעלה מבשר חטאת ואשם וכו' בחמץ או בדבש כתב בין למזבח בין לכבש לוקה וגבי אסור להקטיר על המזבח דבר מכל דברים אלו השמיט כבש ויש לתמוה למה פסק כר\"א במקום רבי יוחנן וכתב הר\"י קורקוס ז\"ל דטעמא משום דסוגיא דבפרק התערובות (דף ע\"ז) כוותיה (וע\"ש תוס' ד\"ה מרבנן וכו' הך סוגיא כרבי אלעזר וכו'):",5,0],[5,6,"המקטיר איברי בהמה טמאה ע״ג המזבח לוקה וכו'. בפרק כל הפסולין (זבחים דף ל״ד) איתמר המעלה איברי בהמה טמאה ע״ג המזבח ר״ל אומר לוקה וכו' טהורה אין טמאה לא ולאו הבא מכלל עשה לוקין עליו ור' יוחנן אמר אין לוקין עליו לאו הבא מכלל עשה אין לוקין עליו מתיב רבי ירמיה אותם תאכלו ולא בהמה טמאה ולאו הבא מכלל עשה עשה א״ל רבי יעקב לרבי ירמיה [בר תחליפא] אסברא לך באיברי בהמה טמאה דכ״ע לא פליגי כי פליגי בחיה והכי איתמר רבי יוחנן אמר עובר בעשה וכו' בהמה אין חיה לא ר״ל אמר אינו עובר עליו בלא כלום ההוא למצוה ואיתותב ר״ל ופירש״י ולאו הבא מכלל עשה עשה כך שנויה בתוך הברייתא ומסקינן בלא תעשה מנין ת״ל אך את זה לא תאכלו אלמא מדאיצטריך לא תעשה אחרינא לאו אזהרה הוא. דכ״ע לא פליגי דעשה הוא דאיכא ותו לא עכ״ל ולפי זה ליכא הכא אלא עשה וזהו שכתב הראב״ד כך לוקה על הקרבתה א״א וכי עדיפא מבעלת מום וכו' ביאור דבריו שכך ראוי ללקות על הקרבתה כיון שלוקה על בעלת מום מכ״ש שראוי ללקות על זו אבל מה נעשה שבגמרא אינו עולה כן. וליישב דברי רבינו יש לדקדק שכתב כשם שלוקה על אכילת הטמאה הבא מכלל עשה כמו שביארנו במקומו כך לוקה על הקרבתה ובפ״ב ממאכלות אסורות כתב מכלל שנאמר וכל בהמה מפרסת פרסה וכו' שומע אני שכל שאינה מעלת גרה וכו' אסורה ולאו הבא מכלל עשה עשה הוא ובגמל ובחזיר ובארנבת ובשפן נאמר את זה לא תאכלו ממעלי הגרה וממפריסי הפרסה וכו' הא למדת שהן בלא תעשה ואע״פ שיש בהם סימן אחד וכ״ש שאר בהמה וחיה טמאה שאין בה סימן כלל שאיסור אכילתה בלא תעשה יתר על עשה הבא מכלל אותה תאכלו עכ״ל וא״כ יש לתמוה מה מביא מאכילת בהמה טמאה שנאמר בה לא תעשה להקרבתה שלא נאמר בה לא תעשה וא״ת דכיון דאין מזהירין מן הדין האי לאו כליתיה דמי כבר כתב הרב המגיד שכיון שנאסרו בלאו הבא מכלל עשה אפשר ללאו שלהם לבא מק״ו ולא מיקרי מזהיר מן הדין וא״כ אין ראיה מאכילתה להקרבתה כלל וי״ל דכיון דבהמה טמאה גריעא מבעל מום כשהזהירה תורה על הקרבתו בלאו יש לנו להביא בהמה טמאה לאסור הקרבתה בלאו מק״ו ויש לחזק דין זה יותר דכיון דאשכחן דאפיק רחמנא בעל מום בלשון בהמה טמאה כדאמרינן בר״פ כל המנחות (דף ק״א) ובסוף תמורה (דף ל״ב) ואם כל בהמה טמאה אשר לא יקריבו ממנו קרבן לה' בבעלי מומין שיפדו הכתוב מדבר כי אסר רחמנא להקריב בעל מום בלאו בהמה טמאה בכלל ומעתה ההיא דפרק כל הפסולים לא הויא תיובתא דכי אמרינן ת״ל את זה לא תאכלו גמל וארנבת שפן וחזיר וילפינן מינייהו בק״ו לשאר בהמה טמאה לאסור אכילתה בלאו הכי נמי כיון שאסר בעל מום למזבח בלאו ילפינן בהמה טמאה למזבח בלאו מק״ו או משום דבכלל בעל מום היא וא״כ כי אמרינן באיברי בהמה טמאה כ״ע לא פליגי לא כדפירש״י אלא היינו לומר דכ״ע לא פליגי דלוקה משום דאזהר עליה בלאו כדאמרן:",1,0],[5,7,"הגונב או הגוזל והקריב הקרבן פסול. בפרק מרובה (בבא קמא דף ס״ו:) קרבנו ולא הגזול.",1,0],[5,7,"ומ״ש ואם נתייאשו הבעלים הקרבן כשר אפילו היתה חטאת וכו' ומפני תקנת מזבח אמרו שהחטאת הגזולה אם נודעה לרבים אינה מכפרת וכו' וכן העולה. בפרק הניזקין (גיטין דף נ״ה) תנן העיד רבי יוחנן בן גודגדא וכו' על חטאת הגזולה שלא נודעה לרבים שהיא מכפרת מפני תיקון המזבח ובגמרא אמר עולא דבר תורה בין נודעה בין לא נודעה אינה מכפרת מ״ט יאוש כדי לא קני ומה טעם אמרו לא נודעה מכפרת שלא יהיו כהנים עצבים וכו' והא אנן מפני תיקון המזבח תנן וכו' כיון דכהנים עצבים נמצא מזבח בטל ורב יהודה אמר דבר תורה בין נודעה בין לא נודעה מכפרת מ״ט יאוש כדי קני ומה טעם אמרו נודעה אינה מכפרת שלא יאמרו מזבח אוכל גזילות בשלמא לעולא היינו דקתני חטאת אלא לרב יהודה מאי איריא חטאת אפי' עולה נמי לא מיבעיא קאמר לא מיבעיא עולה דכליל היא אלא אפילו חטאת נמי דחלב ודם הוא דסליק לגבי מזבח ואידך כהנים אכלי ליה אפ״ה גזור שלא יאמרו מזבח אוכל גזילות ופירש״י בין נודעה מכפר אם נתייאשו הבעלים וכו'. דכליל היא ואמרי מזבח אוכל גזילות. ופסק רבינו כרב יהודה ויש לתמוה שמאחר שרבינו פוסק דיאוש כדי לא קני כמבואר פ״ה מהלכות גניבה היאך פסק כרב יהודה דאמר יאוש כדי קני שזה סותר מה שפסק בהלכות גניבה ועוד דמתניתין לא מייתבא שפיר לרב יהודה דאמרינן בגמרא תנן החטאת הגזולה שלא נודעה לרבים שהיא מכפרת מפני תיקון המזבח בשלמא לעולא ניחא אלא לרב יהודה איפכא מיבעי ליה ה״נ קאמר לא נודעה מכפרת נודעה אינה מכפרת מפני תיקון המזבח והשתא כיון דמתני' כפשטא אתיא כעולא ה״ל למיפסק כוותיה וי״ל דאע״ג דבעלמא יאוש כדי לא קני הכא קני משום דאמרינן בגמרא מתיב רבא גנב והקדיש ואח״כ טבח ומכר משלם תשלומי כפל ואינו משלם תשלומי ד' וה' ותני עלה בחוץ כה״ג ענוש כרת ואי אמרת יאוש כדי לא קני מאי עבידתיה ואסיקנא אוקמוה רבנן ברשותיה כי היכי דליחייב עלה ומשמע דהכי הלכתא מדחזינן דבתר הכי שקיל וטרי רבא אליבא דהאי אוקימתא. ואמרינן בירושלמי (הלכה ו') דרבים היינו שלשה ולא ידעתי למה השמיטו רבינו:",2,0],[5,7,"כתב הראב\"ד ואפילו היה חטאת א\"א אין כאן אפי' עכ\"ל. טעמא משום דמשמע ליה דקאי למאי דסמיך ליה שאם נתייאשו הבעלים הקרבן כשר ויותר היה ראוי להכשיר חטאת שאין ממנה למזבח אלא חלב ודם מעולה שכולה למזבח וכדאמרינן בגמרא וכתבו רבינו בסמוך וא\"כ לא יתכן להביא חטאת באפילו ול\"נ לפרש דארישא קאי שכתב הקרבן פסול וקאמר דאפילו חטאת שהכהנים אוכלים את בשרה אפי' הכי פסול ואינו מתקבל:",3,0],[5,8,"הגונב עולת חבירו והקריבה סתם וכו'. ירושלמי פ״ב דשקלים (הלכה א') ובפרק מרובה (בבא קמא דף ע״ו) גבי מתני' דר״ש אומר גונב קדשים שחייב באחריותן חייב בשוחט תמימים לשם בעלים פריך והרי חזרה קרן לבעלים פי' שהבעלים נתכפרו בו.",1,0],[5,8,"ומ\"ש שם לשם בעלים לאו דוקא דסתמא נמי כשר כדאיתא בריש זבחים לאפוקי שלא לשמו נקט הכי:",2,0],[5,9,"אין מביאין מנחות ונסכים לא מן הטבל וכו' עד ואין צריך לומר מערלה וכלאי הכרם. בתוספתא דמנחות ספ״ח וגם בתוספתא דמעילה ספ״ק ובפרק אלו עוברין (פסחים דף מ״ח) ממשקה ישראל מן המותר לישראל מכאן אמרו אין מביאין נסכים מן הטבל.",1,0],[5,9,"ומ\"ש ולא מן החדש קודם לעומר. איתיה נמי במשנה במנחות פרק רבי ישמעאל.",2,0],[5,9,"ומ\"ש ולא מן החדש וכו'. לא אמנחות בלבד קאי אלא אף אנסכים כדאיתא בפרק כל קרבנות ציבור.",3,0],[5,9,"ומ\"ש ואם הביא לא נתקדשו וכו'. במשנה פ' רבי ישמעאל דמנחות (ס\"ח:) אין מביאים מנחת בכורים ומנחת בהמה קודם לעומר ואם הביא פסול ומשמע לרבינו דהיינו לומר דהוו קדשים שנפסלו ומשמע ליה דהוא הדין לכל אינך:",4,0],[5,10,"כל המנחות אין מביאים אותם מן החדש וכו'. משנה במנחות פרק רבי ישמעאל:",1,0],[5,10,"ומביאים נסכים מן המוקצה ביום טוב. בפרק אלו עוברין עלה מ\"ח ממשקה ישראל מן המותר לישראל מכאן אמרו אין מביאין נסכים מן הטבל יכול לא יביא מן המוקצה אמרת מה טבל מיוחד שאיסור גופו גרם לו אף כל שאיסור גופו גרם לו יצא מוקצה שאין איסור גופו גרם לו אלא איסור דבר אחר גרם לו:",2,0],[5,11,"מצות עשה למלוח כל הקרבנות וכו'. ואין לך דבר שקרב למזבח בלא מלח חוץ מיין הנסכים והדם והעצים. בפרק הקומץ רבה (מנחות דף כ) וכרבי ישמעאל בנו של ר״י בן ברוקא.",1,0],[5,11,"ומ\"ש ודבר זה קבלה ואין לו מקרא לסמוך עליו. איני יודע למה כתב כן שהרי מפורש שם שנתן רבי ישמעאל בנו של רבי יוחנן בן ברוקא טעם לדבריו מה הפרט מפורש דבר שמקבל טומאה ועולה לאישים וישנו על מזבח החיצון וכו' יצאו עצים שאין מקבלין טומאה יצאו דם ויין שאין עולה לאישים יצא קטרת שאינה על מזבח החיצון. ונראה דמשמע לרבינו דהאי דרשא דכלל ופרט וכלל לאו דרשא גמורה היא למעט עצים שנקראו קרבן בהדיא כמו שכתוב והגורלות הפלנו על קרבן העצים ואילולי הקבלה לא היינו ממעטין אותם:",2,0],[5,11,"ומצוה למלוח הבשר וכו'. בפרק הקומץ רבה (מנחות דף כ״א) כיצד הוא עושה מביא האבר ונותן עליו מלח וחוזר והופכו ונותן עליו מלח ומעלהו.",3,0],[5,11,"ומ\"ש כמולח בשר לצלי יש לתמוה דאמרי' התם בתר הכי בסמוך אמר אביי וכן לקדרה ונראה שרבינו היה גורס וכן לצלי וכן גורס הר\"ן וכתב ספר מצות גדול שכן גורס ריב\"א.",4,0],[5,11,"ומ\"ש ואם מלח כל שהוא אפי' בגרגיר אחד מלח כשר. שם תקריב כל שהוא ומפרש רבינו דהיינו שאם מלח כל שהוא כשר ודלא כדפירש\"י ובת\"כ ובתוספתא דמנחות ספ\"ט משמע כפי' רבינו:",5,0],[5,12,"הקריב בלא מלח לוקה וכו': ומ\"ש ואף ע\"פ שלוקה הקרבן כשר והורצה חוץ מן המנחה וכו'. כן משמע מפשט הכתוב על כל קרבנך תקריב מלח למצוה ולא לעכב אבל במנחה שכתוב ולא תשבית משמע ודאי לעכב ובפרק הקומץ רבה עלה י\"ט אמר רב כל מקום שהחזיר הכתוב בתורת המנחה אינו אלא לעכב וכן אמר שמואל אבל ק\"ל דאמרינן שם בגמרא עלה הרי מלח דלא תנא ביה קרא ומעכבא ביה דתניא ברית מלח עולם היא שתהא ברית אמורה במלח דברי רבי יהודה רש\"א נאמר כאן ברית מלח עולם היא ונאמר להלן ברית כהונת עולם כשם שא\"א לקרבנות בלא כהונה כך אי אפשר לקרבנות בלא מלח אמר רב יוסף רב כתנא דידן ס\"ל דאמר בלא מלח כשר א\"ל אביי א\"ה לא יצק נמי לא יצק כלל אלא לא יצק כהן אלא זר ה\"נ לא מלח כהן אלא זר אמר ליה וכי תעלה על דעתך שזר קרב לגבי מזבח ואיבעית אימא כיון דכתיבא ביה ברית כמאן דתנא ביה קרא דמיא ומשמע מהכא דבכל קרבנות מעכב מלח ונ\"ל שרבינו גורס כמו שכתבו התוספות שגורס רבינו תם מלח ברית והוא קרא דכתיב בפרשת ויקרא לא תשבית מלח ברית אלהיך מעל מנחתך אבל ברית מלח עולם היא לא כתיב גבי קרבנות אלא גבי מתנות כהונה עכ\"ל דהשתא לא אמרינן דמעכב אלא במנחה ואע\"ג דמדברי ר\"ש משמע דבכל קרבנות מיירי איכא למימר דכיון דלר' יהודה לא מיירי אלא במנחות נקטינן כוותיה דר\"י ורבי שמעון הלכה כר' יהודה שסובר רבינו דבהא פליגי ולאפוקי מדפירש\"י דלא פליגי אלא במשמעות דורשין ואם תאמר והא מתניתין דלא מלח כשר גבי מנחה כתיב והיאך פסק רבינו דלא כסתם מתניתין וכיון דאפשר לומר דתנא דידן ס\"ל דלא תנא קרא דמליחה הכי ה\"ל למיפסק וי\"ל דמתניתין דלא כר\"י ודלא כרבי שמעון מאחר דאפשר לאוקמא דרב ס\"ל כוותייהו הכי נקטינן ועי\"ל דשינויא דשני בו איבעית אימא מסתברא דלישנא דברייתא כמאן דתנא ביה הוא מילתא דמסתבר הוא ונקטינן כוותיה ויש הוכחה לדבר לומר דלא קי\"ל כהאי סתמא דמתניתין מדאקשי גמרא בפשיטות והרי מלח דלא תנא ביה קרא ומעכבא ביה:",1,0],[5,13,"המלח שמולחין בו הקרבנות וכו'. בפרק הקומץ רבה (מנחות דף כ״א):",1,0],[5,13,"ובשלשה מקומות היו נותנים המלח וכו' עד סוף הפרק. בפרק הקומץ רבה:",2,0],[6,1,"כשם שמצוה להיות כל קרבן תמים ונבחר וכו'. משנה במנחות ס״פ כל קרבנות (מנחות דף פ״ז) ר״י בר״י אומר יין שעלה בו קמחין פסול שנאמר תמימים יהיו לכם ומנחתם תמימים יהיו לכם ונסכיהם ואע״ג דמשמע דרבנן פליגי עליה לא פליגי עליה אלא למימר דיין שעלה בו קמחין שפיר הוי תמימים אבל עיקר דרשא לכ״ע איתא.",1,0],[6,1,"ומ\"ש שלא יביא נסכים לא מיין מעושן ולא מסלת שהתליעה. שם במשנה.",2,0],[6,1,"ומ\"ש ולא יבלול בשמן שריחו או טעמו רע. שם (דף פ\"ו) שמן של ריח רע לא יביא ואם הביא פסול:",3,0],[6,2,"ומ\"ש וכן עצי המערכה לא יהיו אלא נבחרים ולא יהיה בהם תולעת וכו'. בפ\"ב דמדות (משנה ה') כל עץ שנמצא בו תולעת פסול מעל גבי המזבח.",1,0],[6,2,"ומ״ש דה״מ כשהתליע כשהוא לח אבל אם התליע כשהוא יבש גורר המקום שהתליע. מימרא דשמואל בפרק כל קרבנות (מנחות דף פ״ה:).",2,0],[6,2,"ומ\"ש ועצי סתירה פסולים לעולם לא יביאו אלא חדשים. תוספתא פ\"ט דמנחות:",3,0],[6,3,"המקדיש יין פסול וכו'. בס״פ כל קרבנות (מנחות דף פ״ז) בעיא דלא איפשיטא:",1,0],[6,5,"הסולת והיין והשמן והלבונה וכו'. בד\"א שנפסלו או שנטמאו אחר שנתקדשו בכלי שרת וכו'. ברפי\"ב דמנחות (דף ק':) המנחות והנסכים שנטמאו עד שלא קדשו בכלי יש להם פדיון משקדשו בכלי אין להם פדיון העופות והעצים והלבונה וכלי שרת משנטמאו אין להם פדיון שלא נאמר פדיון אלא בבהמה ובגמרא (דף ק\"א) אמר שמואל אפילו הם טהורים נפדים וכו' רב כהנא אמר טמאים נפדין טהורים אין נפדים וכן אמר רבי אושעיא וכו'. איכא דאמרי אמר ר' אושעיא אפילו טהורים נפדים רבי אלעזר אומר כולם טמאים נפדים טהורים אין נפדין חוץ מעשירית האיפה של מנחת חוטא שהרי אמרה תורה מחטאתו ופסק כר\"א דלישנא בתרא דאתי כרב כהנא ור' אושעיא דל\"ק.",1,0],[6,5,"ומה שכתב רבינו שנאמר והעמיד והעריך כל שישנו בהעמדה נערך וכו': וכל הנסכים שנטמאו וכו'. בסוף פרק כל התדיר (זבחים דף צ״ב):",2,0],[6,6,"מי החג שנטמאו והשיקן וטיהרן וכו' אם הקדישן ואח״כ טיהרן וכו'. מימרא בפרק כל שעה (פסחים דף ל״ד):",1,0],[6,7,"זיתים וענבים שנטמאו וכו'. מימרא דרבי יוחנן שם:",1,0],[6,8,"מעלה יתירה עשו חכמים בקדשים וכו'. גם זה שם:",1,0],[6,8,"וכן העצים והלבונה וכו'. משנה (דף מ\"ה) וגמרא (דף מ\"ז:) בזבחים בס\"פ ב\"ש ולשון וכן שכתב רבינו היינו לומר שגם אלו עשו מעלה בהם ואמרו שיקבלו טומאה:",2,0],[6,9,"ואלו הן היינות הפסולין לגבי המזבח וכו'. משנה בפרק כל קרבנות (מנחות דף פ״ו:) אין מביאין אליוסטן ואם הביא כשר וכו' אין מביאין לא מתוק ולא מעושן ולא מבושל ואם הביא פסול ובגמרא (דף פ״ז) והא קתני רישא אין מביאין אליוסטן ואם הביא כשר אמר רבינא כרוך ותני רב אשי אמר חוליא דפירא לא מאיס חוליא דשמשא מאיס ומדברי רש״י נראה דגריס חוליא דפירא מאיס חוליא דשמשא לא מאיס והיא הנוסחא הנכונה ופירש רבינו בפי' המשנה אליוסטן מלשון שמש ר״ל שנותנים אותו בכדים תחת השמש עד שיתבשל ומה שכתב רבינו בכאן נראה שהוא מפרש שאליוסטן הוא שמחממין אותו בשמש ולא נתן בו טעם בישול אבל אם נתבשל בשמש עד שנשתנה טעמו כבישול דינו כמבושל באש.",1,0],[6,9,"ומ״ש וכן יין צימוקין ויין מגתו וכו'. בפרק המוכר פירות (בבא בתרא דף צ״ז).",2,0],[6,9,"ומ״ש ויין הדליות ויין כרם הנטוע בבית השלחין או בבית הזבלים או יין גפנים שנזרע זרע ביניהם או יין כרם שלא נעבד כל אלו היינות לא יביא לכתחלה. במשנה סוף פרק כל קרבנות (מנחות דף פ״ו):",3,0],[6,10,"יין שנתגלה פסול מעל גבי המזבח. בפרק המוכר פירות (בבא בתרא דף צ״ח:) ובסוכה סוף פרק רביעי (דף מ״ח):",1,0],[6,10,"הדלה גפן על גבי תאנה יינה פסול לנסכים. בפרק ב' דבכורות (דף י\"ז):",2,0],[6,11,"סלת שהתליעה רובה וכו'. ברייתא בפרק כל קרבנות (מנחות דף פ״ה:).",1,0],[6,11,"ומ\"ש התליע רוב חטה אחת הרי זה ספק. שם בעי ר' ירמיה ברוב חטה או ברוב סאה תיקו ומשמע דהכי פירושה הא דאמרינן דחטים שהתליעו רובן פסולות היינו כשהתליע רוב כל חטה וחטה אבל אם לא התליע רוב כל חטה וחטה אע\"פ שהתליע רוב סאה או כולה מאחר שלא התליע מכל חטה אלא מיעוטה כשר או דילמא כיון שהתליעה רוב סאה אע\"פ שלא התליע מכל חטה אלא מיעוטה פסול אבל מדברי רבינו נראה שהוא מפרש מי סגי ברוב חטה אחת שתהיה מתלעת אפילו היא מעורבת בסאה חטים שלא התליעו או דילמא לא מיפסיל עד שיתליעו רוב חטים שבסאה:",2,0],[6,11,"וכל סולת שנשאר בה קמח פסולה:",3,0],[6,12,"כיצד בודקין מכניס הגזבר ידו לתוך הסולת וכו'. משנה בפרק כל קרבנות (מנחות דף פ״ה).",1,0],[6,12,"ומ\"ש אבל סולת חטים שנזרעו בבית השלחין וכו' לא יביא לכתחילה ואם הביא כשר. משנה שם.",2,0],[6,12,"ומ\"ש או בארץ שלא נרה ולא עבדה משמע לרבינו דהא דתנן בפ' כל קרבנות כיצד הוא עושה נרה שנה ראשונה וכן מה שאמרו שם בגמרא שעובדה היינו לכתחלה דוקא:",3,0],[6,13,"חטים שלקטן מגללי הבקר וזרעם הרי אלו ספק וכו'. בפרק ר' ישמעאל (מנחות דף ס\"ט) בעיא דלא איפשיטא:",1,0],[6,14,"ואלו הן השמנים הפסולים וכו' עד כל אלו פסולים. משנה וברייתא בפרק כל קרבנות (מנחות דף פ״ה:) חוץ משמן של פגין דתנן התם אין מביאין אנפיקנון ואם הביא פסול ובגמרא (דף פ״ו) והתניא ואם הביא כשר וכו' ל״ק הא רבי חייא הא רבי שמעון ברבי ויש לתמוה למה לא פסק כסתם מתניתין. וי״ל שרבינו היה גורס במתניתין ואם הביא כשר וכך היה גורס רבינו תם.",1,0],[6,14,"ומ\"ש אבל שמן זית שנטעו בבית הזבלים או בבית השלחין או שנזרע וכו' עד ואם הביא כשר. משנה שם:",2,0],[6,15,"כל המנחות והנסכים כשרים מהארץ ומחוצה לארץ עד סוף הפרק. שם במשנה:",1,0],[7,2,"לא כל דבר שאינו פסול מביא אותו לכתחלה וכו' אלא כל שיביא לקרבן יביא מן המובחר וכך היו עושים בזמן המקדש מביאים אילים ממואב וכו' עד ומביאין שמן מתקוע. בפרק כל קרבנות (מנחות דף פ״ה פ״ז:):",1,0],[7,3,"כל העצים החדשים כשרים למערכה וכו' עד ובשל עץ שמן. משנה וגמרא בפ' ב' דתמיד (דף כ\"ט) ובמקום מה שאמרו בגמרא בתאנה דלא עבדא פירי כתב רבינו תאנה של חרשים כלומר של יערים:",1,0],[7,3,"והגיזרין שעשה משה וכו'. מימרא בזבחים פ' קדשי הקדשים (ס\"ב:):",2,0],[7,4,"וכיצד היו עושין בזריעת חיטי המנחות והנסכים וכו' עד ואחר כך זורע. בפ' כל קרבנות (מנחות דף פ״ה) תנן כיצד הוא עושה נרה שנה א' ובשנה ב' זורעה קודם לפסח ע' יום והיא עושה סלת מרובה ומפרש בברייתא ובגמ' נר חציה וזורע חציה. ופי' רבינו בה מבואר ורש״י פי' בע״א.",1,0],[7,4,"ומ\"ש ואם לא היתה השדה עבודה חורש ושונה וכו'. שם.",2,0],[7,4,"ומ\"ש ובורר את החיטים יפה יפה. ומ\"ש ואח\"כ שף את החיטים ובועט בהם הרבה עד שיתקלפו:",3,0],[7,5,"כל החיטים של מנחות טעונות שלש מאות שיפה ות\"ק בעיטה וכו'. משנה (דף ע\"ו) בפרק אלו מנחות.",1,0],[7,5,"ומ\"ש וחושב ההולכה וההובאה בשיפה אחת להחמיר. שם בעיא דלא איפשיטא:",2,0],[7,6,"היין מביא ענבים וכו'. משנה וברייתא שם (דף פ\"ו:) ופירש\"י רוגליות גפנים נמוכים שהוא יפה.",1,0],[7,6,"ומ\"ש ואין מניחין אותן אחת אחת וכו'. שם בברייתא (דף פ\"ז) אין מניחין אותן שתים שתים אלא אחת אחת ואין כן גירסת רבינו.",2,0],[7,6,"ומ\"ש ואינו ממלא החבית עד פיה כדי שיהא ריחו נודף. משנה בפרק כל קרבנות ופירש\"י כשהיא חסרה קימעא היין נודף יותר מכשהיא מליאה.",3,0],[7,6,"ומ\"ש ואינו מביא לא מפי החבית וכו' עד אלא משלישה ומאמצעה. משנה שם:",4,0],[7,6,"ומ\"ש של האמצעית נראה שכך היה גורס רבינו שם:",5,0],[7,7,"ומ\"ש היה הגזבר יושב וכו' עד ואינו לוקה. משנה שם:",1,0],[7,7,"מאימתי מביא מאחר ארבעים יום לדריכתו. משנה בפ\"ו ממס' עדיות (מ\"א).",2,0],[7,7,"ומ״ש עד שתי שנים וכו'. בפרק כל קרבנות (מנחות דף פ״ו:) תנן אין מביאין ישן דברי רבי וחכמים מכשירין ובגמרא (דף פ״ז) מאי טעמא דרבי אמר קרא לכבש יין מה כבש בן שנתו אף יין בן שנתו אי מה כבש בן שתי שנים פסול אף יין בן שתי שנים פסול וכ״ת הכי נמי והא תניא יין בן שתי שנים לא יביא ואם הביא כשר מאן שמעת ליה דאמר לא יביא רבי וקאמר אם הביא כשר אלא אמר רבא היינו טעמא דרבי דכתיב אל תרא יין כי יתאדם וידוע דהלכה כת״ק ומשמע לרבינו דע״כ לא פליג ת״ק על רבי אלא בבן שתי שנים או יותר מעט אבל במיושן יותר לתנא קמא נמי לכתחלה לא יביא.",3,0],[7,7,"ומ\"ש והוא שלא יפסד טעמו. פשוט הוא דלא עדיף ממעושן דפסול:",4,0],[7,8,"תשעה מינים בשמן וכו' עד והשוה והפחות. משנה שם (דף פ\"ו).",1,0],[7,8,"ומ\"ש שהרוצה לזכות עצמו יכוף יצרו הרע וירחיב ידו ויביא קרבנו מן היפה המשובח ביותר שבאותו המין שיביא ממנו וכו'. הם דברי רבינו ראויים אליו:",2,0],[7,8,"בריך רחמנא דסייען",3,0]]);
